import{_ as i,a8 as p,o as h,c as t,ah as o,K as e}from"./chunks/framework.tJjSirE1.js";import"./chunks/theme.BFhW3K9V.js";const P=JSON.parse('{"title":"乒乓球技术精华文章汇编","description":"","frontmatter":{"tags":["life","pingpong"],"abstract":"乒乓球技术精华文章汇编——吴敬平教练谈直板反胶正手拉球的原理、发力要点与训练方法等专业文章合集。","category":["🌱 生活"]},"headers":[],"relativePath":"vault/Knowledge/Life/乒乓球技术精华文章汇编.md","filePath":"vault/Knowledge/Life/乒乓球技术精华文章汇编.md","lastUpdated":1790655645000}'),n={name:"vault/Knowledge/Life/乒乓球技术精华文章汇编.md"};function d(s,a,c,b,u,q){const l=p("NolebaseGitContributors"),r=p("NolebaseGitChangelog");return h(),t("div",null,[a[0]||(a[0]=o('<h1 id="乒乓球技术精华文章汇编" tabindex="-1">乒乓球技术精华文章汇编 <a class="header-anchor" href="#乒乓球技术精华文章汇编" aria-label="Permalink to “乒乓球技术精华文章汇编”">​</a></h1><hr><h2 id="第一部分-【吴敬平教练】谈直板反胶打法与正手拉球" tabindex="-1">第一部分：【吴敬平教练】谈直板反胶打法与正手拉球 <a class="header-anchor" href="#第一部分-【吴敬平教练】谈直板反胶打法与正手拉球" aria-label="Permalink to “第一部分：【吴敬平教练】谈直板反胶打法与正手拉球”">​</a></h2><hr><h3 id="文章一-正手拉球的基本原理与训练方法" tabindex="-1">文章一：正手拉球的基本原理与训练方法 <a class="header-anchor" href="#文章一-正手拉球的基本原理与训练方法" aria-label="Permalink to “文章一：正手拉球的基本原理与训练方法”">​</a></h3><p>《乒乓世界》编辑部给我转来一些读者来信和网上很多直板反胶打法球迷的提问，他们主要是想了解直板反胶正手拉球的基本原理和训练方法，特别是很想学习马林的正手爆冲。很多球迷对正手拉球进行了技术探讨，发表了各自的见解，并且提出了很多问题，有些问题提得十分专业。我看了以后十分感动，对此，我觉得自己有义务把这些年在训练马林和王皓过程中的一些体会和球迷朋友们进行交流。由于我们训练的角度不同，对正手拉球的理解也不一定相同，训练的方法手段也不可能一样。因此，我只能从我的角度把我训练的体会和朋友们交流，仅供参考。</p><p>乒乓球基本上是一项圆周运动，正手和反手拉球都是以运动员的身体重心为轴心、以身体到身体重心的连线为半径进行圆周运动。因此，不管是正手还是反手击球都必须符合这个原理，从这个意义上讲，正手拉球动作的基本原理就是一种力的传递。</p><h4 id="正手拉球的基本要点" tabindex="-1">正手拉球的基本要点 <a class="header-anchor" href="#正手拉球的基本要点" aria-label="Permalink to “正手拉球的基本要点”">​</a></h4><p>基本站位：两腿张开与肩的宽度为差不多相同，身体稍微前倾，重心在前脚掌上，拉球时，身体向右转（以右手为例），重心放在右脚上，在转腰的过程中，用腰控制大臂，右肩稍底，小臂自然下垂，用手腕控制板型，板型前倾（拇指用力压住球板，食指稍微放松，中指顶住球板），板型前倾的角度因来球的旋转不同而调整。</p><p>击球原理：击球的时候，以右手为例，首先是腿上发力，向左蹬腿，身体重心从右脚向左脚转换，交换重心，身体前迎，身体前迎的方向要和击球的方向一致。然后是腰上发力，用腰带动大臂转动，把力传递到前臂，在击球一瞬间，收缩前臂用力击球。从力学的原理讲，正手拉球前，小臂和大臂之间的角度越小越好，这是加大半径，半径越大，初速度就越大，在击球瞬间突然收缩前臂，使半径变小而获得加速度，使速度加快，力量加大。击球时，小臂和大臂之间角度的变化要根据来球和击球的需要进行变化。很多运动员在进行正手拉球时往往只注意了收前臂而忽略了转腰，用腰来控制手臂的发力，或者是注意了用腰的发力来带动手臂而忽略了收前臂，前臂和大臂之间的角度几乎没有变化或变化很小。</p><p>总结起来正手拉球应注意四点：</p><p>1、必须注意重心的交换，重心迎前的方向要和击球的方向一致。</p><p>2、一定要用腰控制大臂，是腰上发力，而不是用手臂发力，注意拉球时腿、腰、大臂、前臂、手腕发力的协调。</p><p>3、击球瞬间必须快速收缩前臂、手腕发力，前臂收缩的速度越快，发出的力量就越大。</p><p>4、击球点必须保持在身体的右前方，击球点离身体越近，越容易控制球。</p><p>有一点值得注意的是不管是什么样的拉球动作，必须和你自身具备的身体条件相符合，只要不影响动作的发力就可以，没有什么固定的动作模式。另外就是在击球前，球板和球之间要有一定的距离，尽量主动去击球，而不要让球来撞你的球拍，或者是球与球拍之间的距离太小，容易被来球顶住，影响你的发力。</p><h4 id="正手拉球的结构变化" tabindex="-1">正手拉球的结构变化 <a class="header-anchor" href="#正手拉球的结构变化" aria-label="Permalink to “正手拉球的结构变化”">​</a></h4><p>对于我国大多数业余乒乓球爱好者来讲，直板居多，随着乒乓球技术的不断发展，打直板反胶的人也越来越多。由于我国的直板反胶打法都是从直板正胶演变过来的，在训练的方法上和打球的意识上都是按照直板正胶的路子和意识进行的。因此，在动作的结构上是以近台为主，动作小，击球速度快，摆速快为指导思想。在正手进攻的训练方法上也很少进行大力量的拉球训练，更多地是强调动作之间的连续性。对于很多曾经经过业余体校训练的球迷来讲，要想对正手拉球动作进行改变就更不容易。这是影响我国直板反胶运动员正手拉球力量不大的主要原因。 在近几年我对直板反胶打法运动员的训练中逐渐认识到了这个问题，因此，在马林和王皓的训练中，改变了以前的训练方法，特别强调了正手大力量拉弧圈球的训练，把这个问题摆在了直板反胶打法训练的首要位置来进行解决。把训练正手拉球的意识从动作小、速度快、连续性好改变为拉球动作舒展、跑动范围大、力量大，连续性好。强调了在大力量拉球的基础上提高拉球的连续性和杀伤力，在平时步法的训练中要求马林和王皓加大拉球的力量，练好大力拉球后的衔接。</p><p>在实际的训练中我主要采用了发大力拉冲从中台发出的下旋球半高球，要求马林和王皓尽量用最大的力量击球，主要训练拉球时动作的舒展性，并让他们逐渐习惯发大力拉球，掌握发力的技巧，把腿、腰、大臂、小臂、手腕的发力协调起来，主要强调了腰腿的发力和身体重心的转换。其次是进行了全台发力拉冲上旋球的训练，主要解决发力拉冲后的连续性和步法的移动。通过训练，使马林和王皓的正手拉球力量有了很大的提高。从比赛的效果来看，我认为在这点上是成功的，这也是在直板反胶训练上的一点突破，打破了直板正胶训练模式的旧框框。对于大多数业余爱好者来讲，要想提高正手拉球的杀伤力，就必须对过去打球的意识进行一些改变，尽量进行一些大力量的拉球训练。</p><h4 id="正手拉球的方法与技巧" tabindex="-1">正手拉球的方法与技巧 <a class="header-anchor" href="#正手拉球的方法与技巧" aria-label="Permalink to “正手拉球的方法与技巧”">​</a></h4><p>正手拉球是一门很复杂的技术，有近台拉球、中近台拉球、远台拉球，有拉上旋球、下旋球，有近台快带、反拉弧圈球，拉半出台球等等。不管拉球有多么复杂，但有一点是最重要的基础，就是步法。步法的好坏，直接关系到正手拉球的命中率、力量的大小和拉球时的调节能力。要想练好正手拉球，就必须先练好步法。而在这一点上，是专业运动员和业余运动员最大的区别所在，业余运动员不可能像专业运动员那样进行大量的高强度的步法训练。但有一点是相同的，那就是击球的技巧。只要能够做到因势利导，充分发挥现有的条件，也会收到一定的效果。下面，我给大家介绍一些比较实用的训练方法和技巧：</p><ol><li>拉好定点下旋球</li></ol><p>1、拉好定点下旋球：拉冲下旋球是直板反胶最基础的基本功，在拉下旋球时除了注意前面提到的基本动作要领以外，要特别注意手腕的用力方法。在击球的瞬间是用手腕去摩擦球，击球点在来球的中上部，在用手腕摩擦球时还要根据来球旋转的强弱再加上一定的撞击。就是人们常说的又摩又打。拉冲下旋球旋转弱的来球要连摩擦带撞击，撞击可稍大于摩擦。拉冲下旋球旋转强的来球必须用力摩擦击球，用自己拉球的力量抵消来球的旋转。在击球的瞬间要特别注意击球时一定要把球往前送，不能力量去硬碰球。这就是我们常说的“吃球”，尽量让球在球板上停留的时间长一些。经常这样训练拉球，你对球的感觉就会越来越好，拉球就会越来越有数，慢慢达到运用自如。训练的方法，在没有多球条件的情况下可采用拉球一方发下旋球到对方的反手位让对方搓长球到侧身位，然后发力拉冲这个球。拉球时一定要注意用全力拉冲，不要考虑下一板球对方是否能够防过来。要的就是让你防不过来。经常这样训练，你的拉球力量一定会提高。在有多球的条件下，可让对方发下旋球到你的侧身位，定点发力拉冲这种球。拉球时要掌握好击球时间，在对方来球跳到最高点或下降前期击球最好。击球时间一定要相对固定，这样容易掌握拉球的命中率，好调节。出界多就向前送一点，下网多就多摩擦一点。在定点拉冲下旋球比较有数的情况下，再把来球的落点扩大到全台的定点拉冲，这样不断加大拉球的难度，拉球的水平就会不断提高。</p><ol start="2"><li>拉好定点上旋球</li></ol><p>2、拉好定点上旋球：拉上旋球和下旋球不同的是，拉上旋球击球点在来球的上部，摩擦球要大于撞击球，击球的瞬间一定要往前送。训练的方法基本和抢拉下旋球一样，只是来球的旋转不一样，是上旋球。在推挡后侧身发力拉冲这板球，或对方变你正手位后发力拉冲，反复练习。有多球训练的条件，可以由对方直接发上旋球到你的正手位和侧身位抢冲，落点可以从定点到不定点，逐步提高击球的难度。</p><ol start="3"><li>练好反拉弧圈球</li></ol><p>3、练好反拉弧圈球：反拉弧圈球是一种高级技术，尤其是业余运动员掌握了这项技术就像如鱼得水，你就掌握了比赛的主动权。因为一般的业余运动员在拉弧圈球时拉高吊弧圈球的时候多，你掌握了反拉弧圈球的技术，你就站在了比对方高一挡的层次上。反拉弧圈球的要领，首先要自己发力，尽量少借对方的旋转，用自己拉球的力量去抵消对方来球的旋转。其次是在反拉时摩擦球一定要薄，摩擦球的上部甚至顶部，既要借对方来球的旋转的力，还要自己发力摩擦球。越是自己发力反拉，命中率越高。越是怕对方的旋转去碰球，越是容易吃对方的旋转。训练的方法，对方发下旋球到你的反手位，你搓球到对方侧身位，对方拉高吊弧圈球到你反手位，你侧身反拉，这样反复练习，等基本掌握了反拉弧圈球的规律以后，再把反拉扩大到全台和不定点反拉。</p><ol start="4"><li>近台正手快带弧圈球</li></ol><p>4、近台正手快带弧圈球：这项技术是防守中很先进的技术，也是很难掌握的技术，是90年代后期才逐渐被采用的技术。在这之前人们在正手位的防守都是平挡，借对方来球的旋转把球挡过去，因而在比赛关键的时刻就很容易因紧张而造成失误，即使不失误，防过去的球也没有威胁，很容易被对方连续进攻。到90年代后期，中国的运动员把反拉的技术运用在近台的防守上，特别是直板反胶打法的运动员运用更多，加快了攻防转换的节奏，收到了很好的效果，马林在这项技术的运用上是非常突出的。这项技术要求运动员的对来球的判断要非常快、准确，手上对球的感觉要求很高，因为有很多球是在失去身体重心或不到位的情况下，完全运动员手上的功夫去完成技术动作。我想虽然目前在业余运动员中能真正掌握这项技术的不多，但已经具备了一定水平的运动员可以去尝试一下，也许你会有意外的收获。</p><p>这项技术的技巧主要在于掌握好击球时间和手腕的用力，击球时间尽量在球的起跳前期（上升期），当步法实在到不了位的情况下，还可以在球刚一跳起时就击球。击球时腰和手腕发力，接触球的顶部。接触球时既要借对方来球旋转的力，同时自己一定要发力去摩擦球，尽量摩擦薄一点，摩擦厚就容易下网，在摩擦球的瞬间一定要把球往前顶。训练方法可采用搓下旋球到对方正手位让对方拉弧圈球到自己的正手位，然后正手近台快带。这样反复练习就会逐渐掌握击球的基本方法，在快带对方从下旋球拉起来的弧圈球比较熟练的情况下，再进行推直线让对方拉弧圈球到自己的正手位快带上旋弧圈球的训练。这样，你就会慢慢掌握在防守中正手近台快带弧圈球的技术。这项技术的关键点是在击球时一定摩擦球要薄，而且自己一定要主动发力去带球。</p><h4 id="正手拉球的注意事项" tabindex="-1">正手拉球的注意事项 <a class="header-anchor" href="#正手拉球的注意事项" aria-label="Permalink to “正手拉球的注意事项”">​</a></h4><p>业余选手在练习正手拉球时，要注意掌握以下几点：</p><ol><li>收前臂</li></ol><p>1、收前臂：在正手拉球时一定要注意收前臂，大臂和小臂之间的角度一定不能固定，要根据来球来决定摆臂的大小。但要注意一点，收前臂一定要用腰来控制。</p><ol start="2"><li>转腰</li></ol><p>2、转腰：由于乒乓球是圆周运动，击球时用腰来控制手是非常重要的环节，击球时球拍的后引不是用手往后拉手，而是用转腰来完成，用腰固定大臂，转腰的速度要远远快于拉手。就是说，在击球前的摆臂是先转腰而不是先拉手。而我们好多球迷们在打球时都是先拉手，不知道转腰，因而在击球时经常出现身体不协调导致发力不集中或发不出力。</p><ol start="3"><li>击球点</li></ol><p>3、击球点：击球点的最佳位置是在身体的右前方（以右手为例），要保持最佳的击球位置就必须学好步法，保持好身体的重心，重心的高低要根据来球来决定。马林经常使用的侧身倒地爆冲是不得已而为之，对方搓过来的球又低又长，拉完以后不可能再还原，只有搏杀。马林在拉这种球的时候重心低，但是击球点是球的最高点或下降前期。正手位大角度的球击球点要根据自己步法移动的情况来决定击球点的高低。一般情况下是在球的下降中期和后期击球。</p><ol start="4"><li>手腕的运用</li></ol><p>4、手腕的运用：在拉球时，手腕要相对固定，不能晃动太大，击球瞬间用中指顶住球板发力摩擦球。另外手腕还具有击球瞬间的调节功能，比如在拉球时突然感到球的旋转比自己预想的要转时就手腕来调节击球的力量大小和摩擦球的部位。在不到位和顶住自己的情况下，就要腰和手腕来调节击球点。特别是在比赛中，很多球都不是很规则，来球的落点也是你最难受的地方，这时候就要手腕来调节，手腕的调节主要大拇指和中指用力来完成。其次拉球时板型的控制也要手腕来完成，有很多的直板运动员正手拉球时吊腕很厉害，这影响发力，一般情况下，手腕和前臂几乎在一条直线上，球板把与手腕之间的角度在45度左右。</p><ol start="5"><li>吃球</li></ol><p>5、吃球：我们看一个运动员拉球的好坏，主要是看他拉球时是否吃球。吃球就是球在球板上的停留时间比较长，而不是球一碰球板就出去了。要做到拉球时吃球，就必须每一板球都主动发力去摩擦球，在平时的训练中尽量少打借力球。拉球吃球的好坏，在平时训练中不是很明显，但在比赛中就有很大的区别。很多球都是在你不到位的情况下要完成拉球的动作，就全你用手腕主动发力去摩擦球来调节，你习惯了主动发力拉球，就能在比赛中控制拉球时力量和击球部位的调节，拉过去很多高难度的球。</p><ol start="6"><li>抢冲上旋球和下旋球的区别</li></ol><p>6、抢冲上旋球和下旋球的区别：动作上没有多大的区别，区别在于抢冲下旋球时击球点在球的中上部，发力的时候根据来球的旋转可带点撞击；抢冲上旋球时击球点在球的顶部，主动发力摩擦球，击球时正手弧圈球技术是乒乓球技术中最基本也是最重要的技术之一。拉好弧圈球的三个要素就是腿、腰、手；三者要协调一致，才能发挥弧圈球的最大威力。</p><hr><h3 id="文章二-直板反胶训练法-专题" tabindex="-1">文章二：直板反胶训练法（专题） <a class="header-anchor" href="#文章二-直板反胶训练法-专题" aria-label="Permalink to “文章二：直板反胶训练法（专题）”">​</a></h3><p>直板反胶打法是我国的传统打法之一，在我国运动员中占有很大的比例。据统计，在近几年的全国锦标赛中，直板反胶打法的运动员约占全体参赛运动员的21—26％。因此，如何面对欧洲弧圈球的巨大冲击，不断探索和创新直板反胶打法的发展方向与训练就成为国家队近年来训练与研究的重点之一。经过这几年的不断努力，我国直板反胶打法的运动员如马林、闫森都在国际、国内比赛中取得了很好的成绩，具备了与世界超一流选手抗衡的实力。但由于相持中的攻防转换能力还没有取得根本性的改变，因而从整个打法上讲还没有取得决定性的突破，因此，这也是我们今后训练中必须重点解决的课题。直板反胶打法的特点是积极主动，先发制人。主要以正手的大范围跑动进攻给对方以致命的打击。这种打法的发展方向应摆脱传统的左推右攻和单面拉的模式，而建立一种全新的模式。</p><p>它主要包括几个方面：</p><p>1、正手的大范围跑动进攻是主体技术，也是这种打法员基本的能力。正手进攻的杀伤力尤为重要。</p><p>2、反手位是推挡和反面技术相结合，反面技术的使用率要高于推挡。因此，必须掌握反面技术。</p><p>3、必须掌握一至两套以上的好发球。实践证明，不管什么打法，没有一至两套好发球很难站住脚。直板打法更是如此。只有在前三板上占优势，才能和横板相抗衡。</p><p>总之，这种打法的技术风格是以前三板为中心，以正手进攻为主线，积极主动，先发制人。当然，其不足之处在于相持中攻防转换能力不如横板，而最终的解决办法还必须依靠反面技术来解决。 正手进攻是直板反胶打法的主要得分手段，正手进攻能力的好坏直接关系到比赛的胜负。因此，在训练中应占有很大的比重。</p><h4 id="一、怎样加强正手进攻能力" tabindex="-1">一、怎样加强正手进攻能力 <a class="header-anchor" href="#一、怎样加强正手进攻能力" aria-label="Permalink to “一、怎样加强正手进攻能力”">​</a></h4><p>具体有以下几个方面：</p><p>1、杀伤力的训练： 这是我国直板反胶打法运动员一直没有解决好的问题。特别是和韩国运动员相比，我们有很大差距，这与我们的训练方法有关。我们训练中很少进行大发力拉冲的训练，讲究板与板之间的衔接，因而动作的幅度相对较小，影响了力量的发挥。要改变这种情况，就必须进行大发力的训练，并在动作结构上注意用力的合理性。乒乓球是一项圆周运动，它是以身体的重心为圆心，以手臂和腰为半径。半径越大，初速度就越大，当半径突然缩短时，就获得加速度，使击球力量加大。因此，动作结构应该是用腰带动手臂向后转，手臂自然下沉，前臂与大臂之间的角度应在130度左右，击球时用腰带动手臂向前，在击球瞬间突然收缩前臂而发出最大的力量。最关键的是在击球时前臂与大臂之间一定要有角度的变化。马林刚进国家队时，我们首先着重解决他正手发力问题。在多球训练中，采用中台喂下旋高球，让马林尽量用最大的力量拉冲。每天保持10—15分钟，主要是训练在大动作拉冲时大臀和腰上的协调用力。经过一个月左右的训练，马林在拉球力量上有了很大的进步，基本解决了正手发力的问题。我认为这种训练方法解决正手杀伤力比较有效。</p><p>2、抢冲两条底线下旋长球的训练 我国运动员普遍前三板球较好，特别是直板运动员的台内球更优于横板。因此，外国运动员在对付中国直板运动员时都是采用劈两条底线长球的战术。因而抢冲两条底线长球是直板反胶运动员必须解决的问题。我们在对马林的训练中，主要采用了两种训练方法。一是在单球的发抢训练中，要求对方以劈两条底线长球为主，主要训练全台抢冲下旋球以及下一板球的衔接。在多球训练中采用一长一短的方法训练以侧身抢冲底线长球为主，配合抢冲正手位长球的能力。二是在多球训练时，注意加快长短球之间的衔接．加大训练难度。</p><p>3、反拉弧圈球的训练 反拉弧圈球是现代乒乓球技术的发展方向，在比赛中被广泛运用。它包括上、下旋的反拉和远、中、近台的反拉、快带。反拉弧圈球的训练既可以在多球训练中单独进行，也可以揉到每个训练计划中去。反拉弧圈球的重点是注意在反拉时接触球的部位。一般的运动员在反拉弧圈球时都是接触球的中上部，容易造成下网或出界。从力学的原理来讲，当弧圈球接触球板时，给球板一个向下的力，同时还有一个通过球心的力，这两个力在接触球扳后产生的反作用力的合力就是球的运行方向。对方拉过来的弧圈球旋转越强，向下的力就越大，通过球心的力就越小，那么球在接触球板后产生的向上的旋转就越强。反之，对方拉过来的球旋转越弱，向下的力就越小，通过球心的力就越大，球在接触球板后产生的向上的旋转就越小。因此，在反拉弧圈球时，只要我们自己的发力超过了球在接触球板后所产生的反作用力，就比较容易掌握回球的运行方向。所以，反拉弧圈时，我们只要接触球的顶部，在自己发力的同时也借来球本身向前的力，球就能比较稳定的反拉过去。特别是在近台快速反拉弧圈球时，接触球的顶部就显得更为重要。因为球速太快，但球的旋转不强，摩擦不够就容易下网。 反拉弧圈球的训练方法有很多，必须根据每个运动员的具体情况进行训练。通常采用的办法是首先反拉好对方从下旋球拉起来的球，可采用多球训练的方法进行。其次是近台的快速反拉、反带，可采用一点拉两点和多球的方法进行。再就是中远台的正手对拉。在反拉弧圈球的训练中，反拉从下旋球拉起来的弧圈球是训练的关键，只要这板球练好了，反拉上旋弧圈球就迎刃而解了。</p><p>4、抢冲半出台球的训练 这是直板反胶运动员必须掌握的技术，在比赛中有着非常重要的作用，它直接关系到前三板的争抢。这也是体现直板反胶运动员“巧”的一个重要技术。抢冲半出台球的训练基本上采用多球训练的方法进行。在发多球时，要注意发球的质量，尽量做到球刚好出台一点点，和比赛的球相似。</p><h4 id="二、精雕细琢前三板" tabindex="-1">二、精雕细琢前三板 <a class="header-anchor" href="#二、精雕细琢前三板" aria-label="Permalink to “二、精雕细琢前三板”">​</a></h4><p><strong>发球的训练</strong></p><ul><li><p>直板反胶由于受到自身打法的限制，主要的得分手段体现在前三板上，而前三板又主要是靠发球抢攻得分。因此，发球尤如直板反胶打法的生命线，没有一至两套好发球就很难立足世界乒坛。从训练的角度看，从小培养运动员对发球的钻研精神和意识很重要，等进入省、市或国家队以后再想练就一手好发球就不容易了。在国家队，我们已经认识到发球的重要性，在训练中练发球的时间安排也不少，可是收效不大。发球好的运动员会不断地去钻研新的发球，而发球不好的运动员总认为自己对发球没感觉，怎么练也没用。其原因就在于要改变多少年形成的习惯和意识很难。因此，要想练好发球，必须从小抓起。这一点必须引起业余体校教练员的高度重视。 发球的种类很多，但近年来由于对发球的创新重视不够，运动员所掌握的发球越来越单调，基本上以左侧上、下旋、转不转为主。而且发球的旋转、落点变化也不够，很容易被对方适应。因此，在发球的训练中要提倡多样化，尽可能掌握与众不同的发球，特别要充分开发直板反面发球。刘国梁的反面发球，在国内外重大比赛中都收到了很好的效果。</p></li><li><p>1、转不转发球：目前欧洲运动员对接侧上、下旋的发球非常适应，但对接转不转发球却很差。因为随着接发球技术的发展，欧洲运动员喜欢采用侧身晃接的方法，侧旋球正好能借上力，而转不转球采用晃接的方法就容易下网或出界。因此，要提倡多练转不转发球。马林、闫森的转不转发球在对欧洲运动员的比赛中都收到了很好的效果。在发转不转球时，要注意落点的变化，比如正手近网短球、中路近网短球、反手小三角以及长球等等。</p></li><li><p>2、正手侧身发右侧旋到对手正手近网短球并配合反手底线长球：这两种发球目前被欧洲运动员广泛采用，而国内运动员现在能发这种球的不多，以至在国际比赛中我们的运动员在接这个发球时吃亏不少。因此，我们必须学会和掌握这种发球。</p></li><li><p>3、直板反面发球：反面发球有两种方法，一是站在侧身位发对方正手近网短球、反手近网短球和直线长球。发出来的球是侧上、下旋球。二是站在反手位用反面发侧上、下旋球。这是具有中国特色的发球，外国运动员往往不太适应，效果较好。希望直板运动员都应该去钻研和掌握这种发球。由于发球的种类很多，以上谈的几种发球只是一种补充，使发球更加多样化。</p></li><li><p>4、右侧旋发球：目前这种发球已被欧洲大多数运动员所掌握，而中国运动员却发得不多，以致在比赛中吃亏不少。因此，我们必须加强这种发球的训练和钻研。 在发球训练时，首先在意识上要明确一点，那就是要想使自己的发球收到好的效果，就必须使对方在接发球时找不到第一时间，尽量使对方在第二时间击球，从而使对方的回球速度减慢，旋转减弱，给自己的抢攻赢得时间。这就要求在练发球时，特别要注意落点的变化。只有将落点和旋转有机地结合起来才能发出最有威胁的发球。</p></li></ul><p><strong>发球抢攻的训练</strong></p><ul><li><p>发球抢攻的训练 发球抢攻的训练包括两个方面，一是发球后的抢攻。二是第三、五板后的衔接。</p></li><li><p>1、发球后的抢攻训练主要强调落点、线路的变化和抢攻的质量。传统的发抢训练都是围绕着左半台进行，右半台只是起到牵制作用。随着技、战术的变化，比赛中从右半台发起抢攻的使用率越来越大。这一点必须引起我们足够的重视。在1999年45届世乒赛单项比赛上马林对瓦尔德内尔第四、五局的比赛中，马林的发球都是从老瓦的正手位突破而取得成功。在1999年日本公开赛决赛萨姆索诺夫对马林的比赛中，萨姆索诺夫在先失一局的情况下改变战术，发短球到马林正手位，由于马林接发球处理不好，被萨姆索诺夫抢冲得手而连输三局。因此，发抢训练必须加强发正手位短球后抢攻的训练，这是发抢技术的一个发展趋势。由于有反手位底线长球和小三角的牵制，接正手位近网短球时身体重心上不去，手在接触球时离身体很远，不好控制回球的落点，容易出机会被对方抢攻。</p></li><li><p>2、发球后第三、五板球的衔接是发抢更高层次的要求。随着控制与反控制技术的发展，接发球经常采用摆短和晃、撇等方法来控制对方的发球抢攻，因而给发抢带来更大的难度。在对方摆短和晃撇不能上手的情况下，这一板球的处理以及下一板球的衔接就显得尤为重要。加强这方面的训练，就使发球抢攻技术更加丰满，不仅能够直接进行发球抢攻，当对方控制时也能通过反控制再进行下一板的抢攻。</p></li></ul><p><strong>接发球及接发球抢攻的训练</strong></p><ul><li><p>接发球及接发球抢玫的训练 接发球技术随着乒乓球技术的发展而发展，在每一个不同时期都有不同的要求。对于直板反胶运动员来讲，接发球技术主要体现一个“细”宇，而这个“细”字又具体体现在以下几个方面：</p></li><li><p>1、台内球的处理，主要是摆短和挑。接发球的摆短，最主要的环节是要抢到第一时间击球，在球刚刚起跳时就要击球。击球时身体重心前迎，用腰控制前臀，手腕在接触球的瞬间突然向下发力，和球往上跳的力形成合力。这样就使摆过去的球很转，使对方不敢轻易挑，只要对方回摆，就有机会抢冲。</p></li><li><p>2、封住半出台球，敢于抢冲。这就要求运动员具有很高的对半出台球的判断力，在此基础上才能谈得上抢冲。因此，在接发球技术中敢于抢冲半出台球是关键，是训练的重点。比赛中处理摆短和抢拉半出台球时，在意识上要明确先是准备摆短，判断球出台时再收回手抢拉。如果先准备抢拉出台球，等判断球没有出台再去摆短，就没有第一时间了，摆短时就不容易控制球的弧线和落点，反而容易被对方抢攻。</p></li><li><p>3、接发球的落点意识。从目前的技术发展来看，更强调摆两个小三角短球的落点意识。</p></li><li><p>4、接发球以后与下一板的防守。这是一个整体，不可分割。必须加强这个意识的培养和训练。它包括摆短以后的衔接、挑球以后的衔接、劈长以后的衔接、抢拉以后的衔接等等。随着乒乓球技术的发展，从正手突破的意识更加明确，接发球直接给正手位的球会越来越多。因此，接发球送对方正手位以后的防守意识显得越来越重要。</p></li></ul><h4 id="三、如何提高相持能力" tabindex="-1">三、如何提高相持能力 <a class="header-anchor" href="#三、如何提高相持能力" aria-label="Permalink to “三、如何提高相持能力”">​</a></h4><p>直板反胶打法的运动员要提高相持能力，首先必须处理好以下几个关系：</p><p><strong>正手进攻与相持球的关系</strong></p><ul><li>这是直板反胶打法的一对矛盾。目前直板反胶有两种类型，一是以正手全台单面拉为主，配合相持。这类打法由于正手的使用率高，在比赛中往往处于积极主动的地位，给对手的压力很大，不足之处是相持和防守的能力相对差一些。马林、闫森属于这类打法。另一种是以近台相持球为主，配合侧身进攻。这类打法的相持和防守能力强，但正手的使用率不高，在比赛中往往处于被动挨打的地位，关健时刻对对方的来球更是防不胜防。王飞、秦志戬、韩阳等就属于这类打法。因此，我提倡以培养第一种打法为主，在充分发挥正手进攻的前提下，提高相持能力和攻防转换能力，因为相持的目的是为正手进攻创造条件。</li></ul><p><strong>正手与反面的关系</strong></p><ul><li>直板反面技术经过多年的创新和发展，已经成为直板反胶打法必须具备的重要技术。但是反面技术的广泛使用也带来新的矛盾，直板运动员往往会出现左来左打、右来右打的情况，像横板一样形成两面攻，这就失去了直板打法的特点。我认为反面技术的运用是为正手进攻创造条件，两者的关系应该是以正手为主、反面为辅。</li></ul><p><strong>推挡与反面的关系</strong></p><ul><li>推挡是直板打法的传统技术，但随着反面技术的运用，推挡与反面技术在使用上发生了冲突。因此，必须根据每个运动员的特点对推挡和反面技术的使用进行一些必要的规范，对什么样的球应该用什么样的技术去处理，应该心中有数。比如，在对马林的训练中，对推挡和反面的运用进行了一些规范：第一板防弧圈用推挡，变直线用推挡，关键时刻的相持用推挡，第一板的防守用推挡(对方发力抢冲时)。相持中对方变线正手抢拉后回反手时用反面，第一板的防守用推挡后伺机转攻时用反面，推挡变直线后对方拉直线时用反面，相持中可以用反面进行相持，扑正手回反手时用反面。</li></ul><p><strong>推挡球的训练</strong></p><ul><li>上面提到对推挡球进行规范的几点，要根据运动员自身的特点进行训练。比如马林所运用的推挡已经不是传统的推挡技术，而是用“围”进行防守。传统的推挡技术在防弧圈和变直线时采用的是平挡或向前下方挤压，过去的球弧线往上走，容易被对方连续进攻。加力变线时容易下网或出界。而马林在第一板防弧圈时都采用了“围”的方法，效果很好。 “围”的特点是能够借上对方的力往前带，过去的球弧线低而且往前拱，给对方的连续进攻造成一定的困难。同时，也把“围”斜线的特点运用到变直线上。过去在防守第一板弧圈球时推挡不敢轻易变线，怕对方正手拉冲两条线防不住。而现在防守第一板弧圈球时，特别是对方反手拉起来的弧圈球用“围”的方法变线，稳定性强，过去的球速快，往往收到意想不到的效果。另外，在关键时的相持球中也采用了“围”的方法，在比赛中都收到了很好的效果。当然，用“围”的方法代替传统的推挡，只是根据马林的特点进行的一些尝试。每个运动员的特点不同，是否用“围”代替推挡，应视情况而定。提出这种方法，只是供大家参考，多一种思路。另外推挡训练中还必须加强切的训练，增加节奏的变化。特别是对轻拉和轻轻快撕过来的球切一板，效果很好。</li></ul><p><strong>反面技术的训练</strong></p><ul><li><p>反面技术的运用除了要掌握好“推挡和反面的关系”之外，在抢拉下旋球方面用得也比较多，特别是对方接发球侧身晃住反手位，自己侧不开身时，反面的抢拉能力就显得尤为重要。在反面抢拉下旋球的训练中，一定要和侧身全台正手进攻结合起来，如果反面拉起来仅仅是为了进入相持，还是摆脱不了被动。抢拉下旋球时一定要注意把身体的重心放在右脚上，拉完球后顺势侧身，调整站位，重心仍然放在右脚上，准备下一板正手的全台抢拉。不要反面—拉就往中间站，形成相持。 在相持中运用反面技术的训练要注意从平挡开始，平挡是基础技术，在此基础上再进行快撕、弹打的变化。</p></li><li><p>在中台运用反面拉冲上旋球时要用中等力量，不要因急于发力而造成失误，反面拉的目的不是要把对方拉死，而是为正手进攻创造机会。 反面技术的使用要尽量做到合理，因而必须分清层次：</p></li><li><p>1、对方发力抢拉，旋转强、能借上力的时候用推挡；</p></li><li><p>2、当对方发不上力或平挡时，可采用反面快撕；</p></li><li><p>3、当对方的拉球旋转强、弧线长时可用弹打；</p></li><li><p>4、在快撕转弹打或直接弹打后下一板的衔接要用快撕，因为弹打后对方防过来的球不往前走，再连续弹打容易失误。另外，反面第一板抢拉下旋球后下一板反面的衔接要借力快撕，而不要发力拉，因为对方防过来的球速度很快，来不及拉手。如果要想连续发力拉，站位必须稍稍往后退一点；</p></li><li><p>5、弹打或快撕以后一定要加强侧身。</p></li></ul><p><strong>相持中攻防转换的训练</strong></p><ul><li>随着乒乓球技术的发展，直板反胶打法在与横板法的相持中，横板反面的快撕占据了主动，直板处于非常被动的地位。这样，如何进行相持以及采用什么手段进行攻防转换，就成为直板反胶打法的一个至关重要的问题。 针对这个问题，我在马林的训练中采取了三种办法：</li></ul><ol><li><p>摆速</p><ul><li>摆速　这是直板反胶在对付横板反手快撕两条线时所体现出来的相持能力。由于目前横板在快撕直线时速度很快，要求马林在定点训练时意识上要跟上节奏，推一板马上准备正手。在定点训练比较熟练的基础上再进行不定点的快速封堵训练，正手位的击球要求到位、快速。这个训练计划在45届世乒赛以前练得不多，但在45届以后，横板选手(不管是中国运动员还是外国运动员)在同马林比赛时都采用了快撕直线的战术，马林也吃了不少亏，所以加强了这方面的训练。</li></ul></li><li><p>近台侧身快带</p></li></ol><ul><li><p>2.近台侧身快带　这个训练计划也是在45届世乒赛以后开始练。在马林与萨姆索诺夫的几次比赛中暴露出这样一个问题，对方反手快撕住马林反手，马林在没有办法摆脱的情况下，采用搏杀的办法侧身近台反拉，但是没有把握，失误很多。为了摆脱这种局面，我们提出了这个训练计划。这个技术在使用上有两个难点，第一是在对方球速非常快的情况下侧身反拉，过去的球只有速度没有力量，而且容易失去重心，对方一旦防过来下一扳衔接不上；第二是在对方快撕两条线的情况下侧身，需要很强的猜球能力。</p></li><li><p>因此，在训练中采用了两个方法，一是反复练习推一板后快速侧身，着重加强身体重心的调节，身体不要往后倒，而重心在击球后快速还原。同时注意击球点要在上升后期，击球时用腰控制手臂发力；二是在多球训练中让对方从下旋拉起，马林近台侧身反拉后扑正手。主要训练侧身时重心的调节以及下一板的衔接。从最近的训练来看效果不错，今后的问题是如何把训练和比赛中的运用揉到一起。</p></li></ul><ol start="3"><li>反面的反拉</li></ol><ul><li>这一点已经在前面的章节中谈过，在此就不在整述。</li></ul><h4 id="四、实用战术的训练" tabindex="-1">四、实用战术的训练 <a class="header-anchor" href="#四、实用战术的训练" aria-label="Permalink to “四、实用战术的训练”">​</a></h4><p>直板反胶打法的战术训练主要是围绕如何发挥正手拉球的威力而进行的，具体包括以下几个方面：</p><p>1、侧身抢冲下旋后扑正手时多拉斜线。扑正手以扑斜线为主，直线为辅，是为了争取形成正手斜线的对拉，再找机会拉直线。要想在比赛中运用这个战术，首先在心理上要相信自己正手的能力，敢于和对方比正手。</p><p>2、正手位抢拉下旋后进入相持或正手全台抢拉。这是直板反胶运动员很关键的—个技术。因为现在欧洲运动员对付直板反胶这种打法都是从正手位突破，主动给你正手，再防—板后进入相持。这种训练有两种方法，一是冲直线后进入相持或正手全台抢拉；另一种是冲斜线后衔接正手拉直线，进入相持或正手全台抢拉。从马林同萨姆索诺夫、瓦尔德内尔、佩尔森比赛的情况来看，当对方搓马林正手位时，在能够发力冲的时候可以多冲直线或中路，位置不好的时候可以多拉斜线形成正手对拉。这种战术在比赛中收到了很好的效果。</p><p>3、推挡变直线后保正手反拉、反带直线。比赛中运动员往往不敢变直线，一是推挡加力变线容易失误；二是推挡变线没有质量又怕对方冲两条线防不住。在马林的训练中也存在这个问题，明明战术需要变线，就是不敢变。在这个战术训练中有两个问题要解决，一是变线的质量；二是变线后的防守。在马林的训练中首先解决变线的问题，由过去的推挡变直线改为“围”直线，提高了变线的质量和稳健性。变线后的防守也由过去的近台防守改为退半步防守，对方拉直线用反面平挡，对方拉正手就用正手反拉。但目前这个技术在比赛中很难运用，因为过去常年形成的意识是用推挡防守，推挡和正手的转换比较快，而用反面挡时，反面和正手的转换意识跟不上比赛的节奏，因而在比赛中变直线后对方拉直线时，防守还是用推挡。</p><p>我认为这个防守技术是今后的发展方向，只要从小培养是能够掌握的。</p><hr><h2 id="第二部分-【李晓东教练】谈衔接、协调与破解波尔" tabindex="-1">第二部分：【李晓东教练】谈衔接、协调与破解波尔 <a class="header-anchor" href="#第二部分-【李晓东教练】谈衔接、协调与破解波尔" aria-label="Permalink to “第二部分：【李晓东教练】谈衔接、协调与破解波尔”">​</a></h2><hr><h3 id="文章一-环环相扣-流畅自如——李晓东谈衔接" tabindex="-1">文章一：环环相扣 流畅自如——李晓东谈衔接 <a class="header-anchor" href="#文章一-环环相扣-流畅自如——李晓东谈衔接" aria-label="Permalink to “文章一：环环相扣 流畅自如——李晓东谈衔接”">​</a></h3><h4 id="衔接-vs-转换" tabindex="-1">衔接 VS 转换 <a class="header-anchor" href="#衔接-vs-转换" aria-label="Permalink to “衔接 VS 转换”">​</a></h4><p>对于衔接的概念，我个人的理解，就是一板球与下一板球之间的关系，它可能是同性球的连接，也可能是不同球的连接。衔接包含的范围比较大，节奏有衔接，力量也有衔接，头一板我方发力打得很重，第二板对方回球很快，如果我仍然倾尽全力去打，球的组合可能就不太合理，不如用一板中等力量，只要出手集中，回球的效果也很好，衔接也很成功，或者头一板重，再用轻力量拉一板加转的球，也叫衔接。</p><p>转换的概念其实与衔接有相通之处，只不过衔接更宏观，而转换，我个人理解就是两项不同技术的连续运用，其范畴存在一定局限性。但从内容来说，转换的难度要高于衔接，比如大家说得最多的是攻防转换，从字面上看是先攻后防，但人们更多追求的其实是先防后攻，这两者都不简单，甚至先攻后防更具挑战性，因为已经“发动”了以后由进攻转成防守，两者的意识有别——进攻发力多，防守借力多；进攻时人的重心前，而防守时重心后；进攻时引拍的幅度相对较大，防守时幅度较小；进攻时容易出手集中，防守时容易“抬”、“架”……这其中都涉及到转换的问题。</p><h4 id="以速度为核心" tabindex="-1">以速度为核心 <a class="header-anchor" href="#以速度为核心" aria-label="Permalink to “以速度为核心”">​</a></h4><p>衔接（转换）概念的提出，与世界乒乓球技战术日趋凶狠、快速的发展趋势有关。其中，速度依然是核心，力量也是通过一定的速度来体现，因此，只要谈到衔接（转换），就会强调对速度的追求。</p><p>个人感觉，衔接（转换）集中体现在前几板球，也就是三、五板和四、六板（或二、四、六板）的关系中，一来其使用频率最高，二来变化比较多。待进入中近台相持后，或许连续两三板球的速度、力量都不会有太明显的差异了，只是不同打法的攻防转换手段有所区别。</p><p>刚到女队工作时，我曾提出“先发动、先下手、抢时空”，其实无非就是用于衔接。先发动，就是先发力，或者先变线，或者先控制；先下手，就是我方要有主动的意识；通过先下手、先发动来抢时空，可上手也可不上手的时候我上，可发力也可不发力的球我发力，可变线也可不变线的球我变线，而且击球节奏始终要比对方稍快一步。</p><h4 id="机枪-vs-大炮" tabindex="-1">机枪 VS 大炮 <a class="header-anchor" href="#机枪-vs-大炮" aria-label="Permalink to “机枪 VS 大炮”">​</a></h4><p>对于力量不足、以速度变化为主的选手，衔接可能更显重要。像金择洙、佩尔森的绝对力量很大，我把他们形容为大炮——迫击炮或者榴弹炮，进攻时“咣咣”一两炮就得分了，而我们自己是机枪——轻机枪或者重机枪，利用自身的爆发力，不给对方喘息机会，你一两板就得手，我连续三四板照样能得分，压得你没有还手之力。当然，“机枪”的力量不能低于必要的限度，这样遇到机会时才能得分。</p><p>1995年43届世乒赛时，就有人提出：中国队的要求是“积极主动、特长突出、无明显漏洞”，没有特点的打法会被认为难成大气，但是孔令辉力量平平、旋转一般、杀伤力也不太突出，只是速度还可以。今天回顾起来，孔令辉之所以能成功，从技术角度看就是由于板与板之间的衔接速度快。用速度辅以旋转作为主要衔接手段并能得分，孔令辉应该是最早的，走在了反胶选手的前列。</p><p>又如谭瑞午，作为男选手，他的身高仅有1.6m左右，体重仅90斤。尽管他比较灵活，但毕竟照顾范围有限，当时在二队里实力并不算强，但是看中了他比较聪明、胆量比较大，于是选上了一队。我带他的九个月，最重要的就是强化了衔接，考虑到他的特点，为他设计了以速度变化为主的打法——“轻机枪”：加快衔接的速度，增加衔接的爆发力，要求他接完发球之后进入相持时，或搓球之后台内挑打时，每次的第一板球都要注重突然性，击球时间比最高点稍早。在最高点击球，对力量比较大的人而言效果还可以，但在选手状态最好的时候，你会发现，主动进攻中（机会球除外），以及快速相持中、控制与反控制中，最佳击球时间都是比最高点稍早，即上升晚期。我就是力争在这个点上，充分挖掘谭瑞午的突然性、灵气和变化，让他用反手开路为正手创造机会，其世界排名也升到了二十多位，遗憾的是，最终他由于非技术方面的原因没有继续打下去。</p><h4 id="转换板型-vs-交换重心" tabindex="-1">转换板型 VS 交换重心 <a class="header-anchor" href="#转换板型-vs-交换重心" aria-label="Permalink to “转换板型 VS 交换重心”">​</a></h4><p>横板：有的人顾反手不顾正手，站位也是右脚前一点，反手发力不错，但正手回球时不调节板型，一来容易造成“身后击球”，二来很可能勾着手腕去打球，像大炒勺似的。相反，有些选手，比如说原来南方的队伍重正手，他们正手击球的板型有些外撇，比较容易发力，但到了这个年代，由于弧圈球被广泛运用，板型外撇太多了就“包”不住球，不易控制弧线，而且若是反手击球时不交换板型，手背、手腕的力量就用不上，反手会显得“站不住”。</p><p>直板：正手攻球时应拇指用力，反手推挡应食指用力。如果正手击球仍然食指用力，就容易抬肘；反手击球仍是拇指用力，则手腕调节用力的方向时，只能向上、向侧，不能向下。</p><p>个人感觉，无论直板、横板，手指、手腕应在正反手转换的每个球中发挥作用，比如横板由正手回反手容易些，食指往下压一点就回来了，而直板的手指动作稍微小一点儿。手指、手腕辅助转换这门功夫要勤练，因其幅度小，产生的抗力也小，有利于加快速度，而且不一定要上台练，随时随地都能练。也有人拿铁拍子练，我觉得，只要注意放松，这也是很好的方法。如果你练得非常熟了，再加上预判，实战中转换时就不会有太大压力。</p><p>但强调手指手腕辅助转换，并不是就不讲究重心了，当来球速度特别快时，只要能保证重心的交换，即使来不及回出高质量的球，也能保证相对理想的击球效果，如果重心不交换，正手可能就会变成“大炒勺”。其实，如果交换得好，就可以少交换，比如，以正手抢攻为主的选手，发完球后转为正手进攻时交换得好，就可以继续正手板型打下去而不必反复交换。</p><p>在我看来，这属于基本功的范畴，但一些年轻选手对此可能不太重视。交换肯定比不交换难，打上升点晚期肯定比打最高点和下降点早期难，但不能因为难，因为你觉得麻烦就不去做，好的东西肯定是更难的，否则就没有公平可言了。在符合自身打法需要的前提下，要力求规范，从小追求最好的东西，难是肯定的，但如果从理论上推敲，你认为它是先进的、是可行的、是你的能力可以承受的，你就去做，一旦你做了，你就会走在别人的前面。</p><h4 id="正三角-vs-反三角" tabindex="-1">正三角 VS 反三角 <a class="header-anchor" href="#正三角-vs-反三角" aria-label="Permalink to “正三角 VS 反三角”">​</a></h4><p>从台内球转入相持，很多人马上退下去，手拉后了一副张牙舞爪的样子要去跟人家打相持，其实，往往因为对方来球速度比较快、前冲力比较强，造成来球把你“顶”在后面，形成“身后击球”，十分被动。所以，训练中我有一个提法：手在台面上、手在身体前面、手在肘前面，这样我的击球位置和击球距离是比较舒服的。</p><p>对于这种快速来回中的衔接（转换），也可以用“截击”的概念来解释。把人与来球组成一个三角，比较正确的方式，人的身体应是三角的中心，由中心向左、右的前上方挥拍，这样我就在“截击”，需要照顾的范围小，又能保证身前击球，无论发力、借力都容易。如果变成球是三角的中心，以球为起点向两旁延伸，打成一个反三角，左右两边无限制扩展以后，回球难度就大了。</p><h4 id="力量合理-出手集中" tabindex="-1">力量合理 出手集中 <a class="header-anchor" href="#力量合理-出手集中" aria-label="Permalink to “力量合理 出手集中”">​</a></h4><p>我来国家队之前，在北京男队工作了十几年，师傅是岑淮光教练，他对相持有一定研究。有人说，北京队实力强，是不是练习回合特别多？其实，我们训练中并没有刻意追求摆速要多少板，而是当时对力的研究比较多，把力量分成几份。比如：十成力，也就是“发死力”了，我们不太赞成；出了机会，八九成力够了；主动进攻六七成，相持四五分劲，防御三四分或者两三分。我们提倡中等力量和借力中发力，提倡在上升晚期击球，在这个点上，来球的旋转没有完全出来，又同最高点一样是发力的良好时机，而且速度快、隐蔽性强，如果等到最高点再出手，速度慢下来了，手拉大了，击球意图也暴露地比较明显。只要做到力量合理，回合自然不就多了吗？再者，出手要集中，这样既保证了突然性又可以充分体现爆发力。我可以退得不是太后，不至于狼狈招架，你打不动我，我两成劲借上你的八九成劲，回过去威力一样不小，从场面上看也不是下风。找好位置，找好距离，创造一个比较舒服的击球条件，这在转换中是比较有用的。</p><h4 id="手段全面-突出特长" tabindex="-1">手段全面 突出特长 <a class="header-anchor" href="#手段全面-突出特长" aria-label="Permalink to “手段全面 突出特长”">​</a></h4><p>衔接手段还是要精练。比如弧圈球相持或者防守中的转攻，当你站位近台时，如果来球的弧线比较高、旋转比较强、节奏比较慢，用反撕处理就比较难，不妨用一板反手弹打——这个球是瓦尔德内尔发明的，后来马文革、孔令辉用得比较多，如果弧线比较低、旋转比较正常，可能用一板快带、快拉（术语叫反撕）来转攻效果更好。</p><p>反手，尤其是反胶选手的反手，到底用什么衔接手段好？今天的乒乓球，不仅需要特点突出，也强调技术全面，反手在相持、攻防转换中仅有反撕或弹打都是不够的，对旋转很强、弧线很低的还可能采用平挡，因球制宜。当然，三、四种手段不能平均分配，还是要形成自己的特长：如果反撕能力强，反撕的比重要大一点，如果这球可挡可撕，你可以反撕，可敲可摩擦时你可能采用摩擦多些，反之亦然，撞击能力强的人，撞击比例就多一点。从趋势来看，现在是速度加旋转的时代，我个人认为加旋转的球威胁更大些。举例来说，刘国梁开创了直板横打的先河，原来反手不能拉下旋，他能拉，原来反手相持都是平挡，他可以敲打，但由于时代和打法的关系，他反手摩擦的能力相对来说稍弱，而王皓、马林、阎森现在只是在慢节奏中敲一板，相持中则不太敲，都是采用旋转与速度相结合的方式，比如对方拉弧圈后我们可以反撕，对方平挡后我们快拉或是快撕。</p><h4 id="取长补短-世界大同" tabindex="-1">取长补短 世界大同 <a class="header-anchor" href="#取长补短-世界大同" aria-label="Permalink to “取长补短 世界大同”">​</a></h4><p>我有一个观点——“世界大同”，就是说各国打法都在追求理想的境界，而且追求的结合点可以说越来越集中，无非就是积极主动、凶狠变化。就好比我们都去北京，我的方法可能好点，算是从上海走，我先到，他从海南走，尽管慢点，但也是在走，最终的目的地还是比较一致的。大家都在取长补短，为什么说瓦尔德内尔对世界乒坛有比较大的贡献，是因为他的发球抢攻、反手弹打弧圈、接发球晃撇等等都被广为采用了，同样，中国选手的许多东西也在为欧洲选手所借鉴。</p><p>譬如萨姆索诺夫，也是个子高，整体实力较强，就我个人的观察，他同样在解决衔接的问题。他采用的方式，首先是多用长球开路，争取在上旋中的衔接（转换），尽量避免近与远、台内与出台这种前后距离的转换，这样在原位置挑打、撇，然后形成长球上旋对攻就比较容易，这与王励勤类似；其次，萨姆索诺夫比较注重每板球的技术质量，比如劈长时砍得很深、出手速度很快、旋转比较强，或者相持中令对方感觉球非常“顶”，这有他自身发力的原因，另外我也听说他用的海绵比一般人厚一些，球拍弹性更大。当然，正反手的转换相对而言较易解决，但中间仍是他比较明显的一处软肋，这对重心、移位都有很高的要求，对个子高的人来说难于解决。</p><p>我原来做过一个粗略的统计，个子较高的选手，女子身高超过1.7m，男子超过1.8m的，普遍被认为比较软、比较慢。但是王励勤仍然保留了平常身高的优势，所以，基础较好、有发展潜能的选手，在年轻时一定要加强对体能的训练，现在你可能觉着自己的体能够用，将来却未必能保持下去，特别是女孩子发育之后，身体胖了，如果胆量再小点，马上就会觉得体能力不从心了。换句话说，在小的时候，即使当时的体能够用，还要再加强到超前些，因为以后要打点折扣。</p><hr><h3 id="文章二-李晓东——协调性的六个关键词" tabindex="-1">文章二：李晓东——协调性的六个关键词 <a class="header-anchor" href="#文章二-李晓东——协调性的六个关键词" aria-label="Permalink to “文章二：李晓东——协调性的六个关键词”">​</a></h3><p>体育有运动的美感，竞技有实用的需要，两者怎样合二为一？在我看来，对乒乓球这项富于技巧和技术的运动来说，协调就是答案：仅仅动作“顺”，欠缺杀伤力、击球质量不高，不是完整意义的协调；仅仅威胁大，命中率不高，也称不上协调。――协调性，象征着外在的观赏性达到高度统一。乒乓球是全身运动，从下往上数，踝、膝、髋、腰、肩、大臂、前臂，手腕、手指…….缺一不可，腿、髋、腰更多是大肌肉群的协调用力，而乒乓球的球体轻、速度快、感觉细腻，因此神经末梢的感觉也很重要，大肌肉群的力量最终如何通过小肌肉群得到体现？这就是对协调性的考验。</p><p>小时候协调性的基础打得不好，十二、三岁从体校进入专业对时还有希望改，如等到十四、五岁进入国家二队，在去改动作，往往积重难返，鲜有成功。所以协调性的好坏，也意味着你的发展空间宽还是窄。再者，协调性好，会提高你所能承受的相对运动负荷的强度，有助于减少伤病的发生，举个例子，按道理说，击球中持拍侧的肩通常是沉着的，但有些人的动作缺乏协调，打球时，打球先把肩挺在外面，对肩关节的运用不合理，导致受力过多，出现伤病，其实受力点根本不应该在肩那儿。</p><h4 id="握拍-顺势顺序-适中兼顾" tabindex="-1">握拍 顺势顺序 适中兼顾 <a class="header-anchor" href="#握拍-顺势顺序-适中兼顾" aria-label="Permalink to “握拍 顺势顺序 适中兼顾”">​</a></h4><p>握拍是身体与球拍的衔接点，此处相差分毫，对你动作的外形、手上击球的感觉都会产生巨大甚至决定性的影响。如果握拍不合理，就容易使动作发紧，直接影响实战表现。拿日式直板来说，其握法中，后面三个手指直顶着，因此正手发力回击出台球的能力比较强，很顺，但到了反手、台内，就会受到限制，发僵、不协调。</p><p>无论何种握法，都要讲究顺势、顺序。比如直板的握拍，食指。中指、虎口三个支点，食指和中指三占其二，在正手攻球时起的作用非常大，如果它俩同时在同一条线上使劲，就会彼此产生抗力，破坏动作的协调性，此时，若用拇指帮助转动，效果就会好一些。</p><p>争论最多的，还是关于正反手击球时板形是否需要交换。我个人的观点，是要适中、兼顾、合理。在快速的来回中，你说握拍方式没有丝毫变化，还能兼顾左右两边，我觉得不太可能，还是需要一些交换；反过来说，如果两边交换的太大，恐怕也实在来不及。还是以直板为例，正手攻球时拇指起的作用比较大，如果反手推档、反手攻球时拇指在倚重拇指，就会压不住来球，结果，很多人到反手时食指用力，拇指翘起来，殊不知，拇指翘得高了，在换回正手击球会受到影响，因此并不合理。同样注重推档的人，在推档中食指用力，这没问题，问题在于，若正手攻球时还让食指起决定性作用，与中指、虎口就难以配合了，容易造成身后击球、抬肘、晃动。横板也一样，如果握得很深，跟日式直板类似，可能正手出台攻球、弧圈球比较稳定，但搓球得旋转、台内球得处理会发僵；如果握得很浅，台内球好控制，但回击出台球的动力定性也易产生问题。所以，握拍的时候，要综合考虑到正反手的关系，基本的握拍方式不要有太大的变化，而实际运用中一定要求细微的调节，尤其是手指、手腕要发挥作用。</p><h4 id="同一-上肢下肢-同时同向" tabindex="-1">同一 上肢下肢 同时同向 <a class="header-anchor" href="#同一-上肢下肢-同时同向" aria-label="Permalink to “同一 上肢下肢 同时同向”">​</a></h4><p>乒乓球的击球用力，基本是一个自下向上的力量传导过程，说得玄点，有些象武侠小说里描述的，把力量从脚贯穿到手腕、手指上，而且这种贯穿得有技巧，应该是畅通无阻的，既能有发力又能又调节。不少女孩子，打球时下边不使劲，全胳膊、上身，回球容易发空、发飘。所以，我们提倡从下半身开始发动，因为下半身的力量更大。上下肢的配合，对促进动作的协调性至关重要，我将之归纳为两个同一性――上肢与下肢同一时间，朝同一方向发力。这样，力量的使用就比较经济、合理。有的人，下肢先使劲，上肢后使劲，容易去“够球”，因为身体已经失去了支点；反之，要是手先使劲，就会影响步法移动，动手不动脚或者用手迁就腿的人，通常显得步法差，也很容易身后击球。</p><p>应用这种“传导”的概念，我们也更容易去寻找动作不协调的根源――由下往上找。</p><h4 id="轨迹-相对一致-局部微调" tabindex="-1">轨迹 相对一致 局部微调 <a class="header-anchor" href="#轨迹-相对一致-局部微调" aria-label="Permalink to “轨迹 相对一致 局部微调”">​</a></h4><p>无论哪个项目，也无论多么复杂的表象，其原理提炼出来，都应该是简单、干净、明了的。在乒乓球中，不管哪个动作，身体和手的的运行轨迹应是基本一致的，尤其是手臂的轨迹，我觉得在空中运行时，中途变向未必合理，容易造成动作走形，偶尔或许能打出一两个好球，但长此以往，用这种方式作为自己的主体动作，是很不稳定的。</p><p>当然，整体轨迹的相对一致，并不否定局部调节的必要，但这种调节应该交给手指、手腕去完成。比如，这个回球下网了，我的手指(主要是中指)可以往上多摩擦一些，手指摩擦不够，重心的发力方向可以再往上些，重心和手指的摩擦还不够，板形不妨再亮一点，但我的运行轨迹是不变的。无论攻打上旋还是下旋，无论发力多还是借力多，如果你的动作外形差异比较小，彼此结合得比较紧密，对你的衔接转换将大有裨益，动作也会更协调。</p><h4 id="重心-帮助发力更助还原" tabindex="-1">重心 帮助发力更助还原 <a class="header-anchor" href="#重心-帮助发力更助还原" aria-label="Permalink to “重心 帮助发力更助还原”">​</a></h4><p>重心与手基本是一体的，而绝不是分离的。所以，在不夹臂的前提下，我觉得手如果能离身体近一些，就能比较好地利用重心的力量，两者的结合会稍微容易一点，动作也会更协调。对于重心帮助发力，大家都比较好理解，但其实重心的作用远不止于此，无论正反手衔接、发球、搓球…重心的影子无时不在。马林发球好，他说，“我发球，肘以下是松的，沾球的时候我发力，但是我身上其它地方都适度紧张，都要吃住点劲，我沾球的—刹那，手、重心也是同一时间同一方向点一下。”还有人说，“发球，第一跳我用重心找点，稳定系数更高。”接弧圈也是一样，大多数时候，就算板形垂直接也没关系，只要重心用力的方向往下，击球时间掌握好了，也不会接飞，如果反冲反带只手的力量，板形压到180度，打滑了也未必管用，包括对拉中控制弧线…·-重心都是你的底气，它能解放你的手，让手上的压力小很多，还更稳定。</p><p>我着重想讨论的，是以重心带动手臂还原。假设还原只以手臂为主，手臂攻球时前进的幅度可能是两尺多或者三尺，如果还原还是这么大的距离，每打一板球，手就需要工作六尺，几板快速来回之后，由于频率太高，手就已经僵硬了，没感觉了。如果你能用重心帮助还原，在快速连续中几乎不用明显引拍就可以还击，因此能给手以更大的自由，利用节省下来的这段时间，你的手可以放松，可以比较从容地去找击球点、去取位…好处无穷。</p><p>实践中，还有一点经常被忽视，就是右手握拍的人不注意左半身的配合，左手握拍的人不注意右半身的配合，削弱了左右的协调性。以制动为例，如果右手选手发完力，左半身不吃住力，任由击球动作随贯性越过身体中线之后，再还原回来，幅度就太大了。如果动作行进到中线附近，左半身帮点忙制动，你的身体再往右后方还原就会容易许多，包括从正手回反手也是类似的道理。人的身体具有很多对称性：左肩往后，右手就能挥出去，如果左手顶在前面不动，右手都出不来；接弧圈，左肩往左后抬一下，右手很自然地就往右下方走了；包括攻球、推挡…都需要引起重视。</p><h4 id="引拍-松而不晃-紧而不僵" tabindex="-1">引拍 松而不晃 紧而不僵 <a class="header-anchor" href="#引拍-松而不晃-紧而不僵" aria-label="Permalink to “引拍 松而不晃 紧而不僵”">​</a></h4><p>引拍有引拍的技巧。在由后往前的过程中，有很多人盲目地想发力，从拉手开始，手就已经处于高度紧张的状态了，导致整个挥拍过程中，再没有加速的能力，看起来用劲很大，实则费力不讨好，出球很僵，影响了手上的感觉，回球效果也不佳。</p><p>其实，如果把迎前的过程分为两尺，第—尺中，你使两到三成劲差不多就够，最理想的境界是“松而不晃、紧而不僵”——放松，但不晃，晃就容易甩了；紧张，但只是适度承点力，太多力就起反作用了。这样，才能为真正的击球赢得力量、赢得时间。而在即将击球的最后一尺当中，就要把这一尺的精华充分展现出来——包括击球的击、擦、转动、制造弧线、调节，都在这一尺内完成。如果掌握好了这点，对于提高空间感、节奏感都有好处。</p><p>很多人，对低球突击、拉冲还比较在意，一遇到高球，胳膊一抡就算完事。但邓亚萍却不是，她打任何一板球对弧线都有要求，大里面包含着非常细腻的小，总是力求把那“一尺的精华”体现出来，包括打高球，她会要求打出来的球通过自己的食指、虎口往下压送，让弧线能由上往下地走，所以命中率高，这就是她高人一筹之处。而更多的人，突出不了那一尺的爆发力，技术细节更没深想。</p><h4 id="连贯-行云流水-旱地拔葱" tabindex="-1">连贯 行云流水 旱地拔葱 <a class="header-anchor" href="#连贯-行云流水-旱地拔葱" aria-label="Permalink to “连贯 行云流水 旱地拔葱”">​</a></h4><p>打乒乓球的人，极端来看，分两类——</p><p>一类人，不引拍，就在原地收缩，或者提前引拍很多，引完拍瞄着、等着，每打完一板几乎就要停顿一下，容易原地下坐，跑起步法踉踉跄跄，既不流畅又很费力，属于“旱地拔葱”；</p><p>另一类人，每板球都在行进之间，有重心交换，至少有小的引拍，还原、引拍与出手环环相连，从不间断，充分利用动作的惯性，显得自如协调，我们称之为“行云流水”。</p><p>你愿意属于哪—类?恐怕没人会选择“旱地拔葱”。我的理解，决定你是否能“行云流水”的关键，在于你打球是否符合连贯理论。在整个击球过程中，重心交换应该是不停顿的，重心走出的小橄榄形(或称枣核形)轨迹是循环不息的，这样才能加强协调性，并在客观上提高回球的质量。当然，根据每个球的快慢，这种连贯在节奏上要有点调节j，不要让它停顿：比如球来得慢，你的重心交换可以慢一点，引拍可以慢点，动作略微大点，击球距离大点，使用力量大点，但慢到不停顿，比来球稍快点就行；如果球来得快了，我引动就快点，动作幅度小点 主动进攻，中距离、“中重心”、中力量；防御和快速相持，小动作、“小重心”、小距离——但是，不能没重心，出手不能不集中。</p><p>需要注意的是，这种连贯，主要是由后往前的，而不是上下起伏的。高水平的选手，我说个笑话，他打球日寸身体的高度都差不多，整个人基本在一个水平线上不间断地运动，所以流畅协调。相反，如果“坐”在那儿一起一伏，起来下去需要时间，再由后往前还需要时间…就难免不“旱地拔葱”了。</p><p>讨论了六个关键词，说到底，怎样的动作才算协调的好动作？我想有个检验标准，这个标准不能求全责备，因为不同的人，握拍的手形不一样，感觉也不是太一样，你说王励勤、马林是好动作，就让所有人模仿他们？不可能也不可取。女国手里，王楠、张怡宁正手拉球有点“撇”，郭跃拉球就有点“包”，孰有孰劣？实际上无关高下。真正的衡量，我想，是看你有无做到――能紧能松，能身前击球，能发力、摩擦，有细微的调节――－这几点就足够了。</p><p>如果只注意动作的外形，而不注意内涵，就可能走向另一个误区。我原来有位师兄，动作特别漂亮，外号“宣传画”，意思是他的动作可以当教科书贴在那儿，但是他的实战水平与动作并不相称，因为他沾球那一下，出手不够集中，击、擦的感觉不太好。所以，动作看着很顺，似乎没有毛病，并不等于真的没有问题，如果在完成动作过程中，一味地放松、求顺、集中就有违协调的本意了。不要觉得一发力就是僵，合理的发力应是有松有驰，发力的时候紧，放松的时候松，这也是一个技巧，大家可能现在比较重的是发力的技巧，但相对忽视了放松的技巧。</p><hr><h3 id="文章三-解密波尔-七剑" tabindex="-1">文章三：解密波尔&quot;七剑&quot; <a class="header-anchor" href="#文章三-解密波尔-七剑" aria-label="Permalink to “文章三：解密波尔&quot;七剑&quot;”">​</a></h3><p>世界乒坛，永远是强中自有强中手，一山更比一山高。虽然超一流选手的名字我们耳熟能详，但真正比较起来，目前还是有三个人的实力明星稍高于其他选手。他们就是王励勤、马林和波尔。用刘国梁的话来说，王励勤是以速度力量为主，马林是以旋转变化为主，也有一定速度，波尔则是位居其中，可以说是集王、马两人之所长——虽然速度比王励勤慢点，但慢不了多少，力量是小点，但相持转攻的能力不在王励勤之下；虽然搓球的旋转比马林差点，但拉球的旋转绝不亚于马林。如果王、马能百分之百的发挥，对波尔将略有上风，但若稍有闪失，波尔就是对中国队威胁最大的选手。那么，波尔到底有那些看家本领，以至能得到中国队、如此青睐呢？现在就让我们一一解密。</p><h4 id="第一剑-拉下旋来球先转后冲" tabindex="-1">第一剑：拉下旋来球先转后冲 <a class="header-anchor" href="#第一剑-拉下旋来球先转后冲" aria-label="Permalink to “第一剑：拉下旋来球先转后冲”">​</a></h4><p>第一剑 拉下旋来球先转后冲组合好手腕转动压弧线</p><p>在欧洲选手中，波尔的速度之快令人印象深刻，但是我们回忆一下，他的第一板上手，除了对半高球，都是拉加转弧圈，而不是像绝大多数中国选手以冲杀为主。为什么你明知他拉加转，他还是能对所有人形成威胁，而且你觉不出他慢？</p><p>答案是：他的拉球旋转非常强，而且弧线非常低，落点同下一板连续拉也十分配套。对右手，他很少会拉到你的正手位，多是拉到你的反手、中间位，这样你回到他正手位的几率就非常高，他再连续拉冲。如此一来，他第一板上手慢，第二板进攻快，一慢一快，就有了明显的节奏变化，所以你可能觉得他非常快，其实细分析，他对你的打击主要还是第二板进攻的快。因为他拉的加转弧圈既转又低且落点好，你很难加力、转攻，只要你用平稳的方法回球，他就达到了目的——不求一锤定音，而是通过两板、三板的组合，尤其第一板与第二板这种加转与速度的组合，给对方以很大压力。</p><p>波尔的两脚分开站立。而中国的教科书一般主张两脚开立稍宽于肩，但据测算波尔的两脚间距通常都在一米甚至更大，与众不同。波尔发球后站位较近，因为发球质量较高，对方不太可能出重手挑打，而且他善于拉半出台球，这种站位利于发挥自身特长。</p><p>波尔抢拉下旋球的精华所在：</p><ul><li><p>重心压低 一般人正手拉球时两腿的夹角35-40度，波尔却时常超过90度，测算值最多达到105度，因此两脚撇的很开，重心压的极低。</p></li><li><p>腰髋发力 波尔下半身撇开后，保持站位不动，与上半身的夹角夹的特别紧，全髋关节发力，受力很大。</p></li><li><p>手腕后引 手腕向后下方引拍明显，保证了挥拍迎球时手腕运动幅度较大，有利于加快加速度。</p></li><li><p>下压弧线 有的人拉加转，就是沉低手使劲摩擦，虽然拉的转但是弧线高，对方适应以后照样可以反拉反冲。为什么波尔的加转拉的低？关键是触球后手腕有个转动。这种转动既是摩擦球也有助于往下压弧线，包括他的重心，也有类似的下压过程。这样就保证了拉球旋转超强而且弧线低，为他下一板的进攻做了非常充分的准备。</p></li></ul><h4 id="第二剑-侧身拉球" tabindex="-1">第二剑：侧身拉球 <a class="header-anchor" href="#第二剑-侧身拉球" aria-label="Permalink to “第二剑：侧身拉球”">​</a></h4><p>第二剑 侧身拉球</p><p>腰髋拧侧身重心压弧线手臂撇落点异向但同时</p><p>波尔的侧身拉球，尤其拉斜线，有独到之处。中国选手侧身，多用小碎步垫几下，两脚离的不是太开，波尔却不同，他在持拍手异侧脚（右脚）跨到位后，吃拍手同侧脚（左脚）并不太跟进，而是保持两脚分得很开，“下边不动，上边动”，几乎全腰髋的转动或者说“拧动”来完成侧身。</p><p>波尔在拉球时，身体重心是向自己的右下方压去，压至几乎倒地，转腰幅度非常大：而持拍手是撇着向左前走，与重心方向相反。压重心能够控制回球弧线的高度，将其压低。撇手是为了控制弧线方向，让回球具有“滑板”的威力。</p><p>类似的撇拉，不仅可用于侧身正手进攻，也可用于在正手位回直线。需要强调的是，拉这种球，压重心和手迎前的时候务必要一致。既压又击，压的劲才能作用的上，压早了可能下网，压晚了跟没压一样容易出界，一定要把两种劲“含”在一起，才能协调、晃动性强。</p><p>波尔这种“拧腰”侧身方式的好处在于，击球时双脚不动，双脚都在受力，站位不易乱，所以别看他腰拧着，“拧”完后脚下不乱立即可以还原，假如侧身时垫步、交步用的过多，还原速度自然会比波尔慢。像刘国梁、马林这样本身很灵活、小碎步很多的人，照搬波尔的侧身方式未必有意义，但如果你本来步法就慢、重心交换又还不错，就不妨向波尔学学“拧腰”侧身——前提是你经过足够的系统训练。</p><h4 id="第三剑-反手反攻" tabindex="-1">第三剑：反手反攻 <a class="header-anchor" href="#第三剑-反手反攻" aria-label="Permalink to “第三剑：反手反攻”">​</a></h4><p>横向发力撕开角度</p><p>看过不来梅世乒赛中德之战的人，一定对波尔频频用反手反攻王励勤的拉球记忆犹新。按说，王励勤抢拉半出台球的水平在中国选手中并不算差，但波尔却能用反手 直接 发力反攻。中国横板选手在反手位解决湖圈球时，多用挡、拱、快带等技术，以不丢球为主，但波尔却能在近中台反手反攻甚至反拉上旋球，这无疑是一项很有创新意义的突破，这意味着乒乓球技术攻打上旋球从此无死角。</p><p>其实，波尔反手反攻的绝招，在两年前对萨姆索诺夫的这场比赛中就已初现端倪：在比赛中，萨接发球时抢先用反手将球挂起，应该说这板接发球还是不错的，因为萨擅长退台相持球，接发球时主动发动长球有利于形成对攻局面，不容易打乱自己的站位，避免了由前往后、由攻转防的转换。但波尔早有准备，他直接用反手发力反攻斜线，接着准备侧身连续正手进攻，直接就用大角度调动撕开了萨的防线，形成了随后调正手打反手的有利局面。</p><p>波尔反手之所以能够直接发力反攻，一是手位比较高、击球比较早，二是动作并非直接往前，而是有横向发力的成分，即左手挥拍的他挥拍方向往左较多，这样自己不必主动制造弧线，回球反而又低又快，还有助于抵消来球的旋转。以前我们介绍过格林卡相持几板后能有这种横向发力的球，但波尔是前几板就有，更为先进。当然，波尔反手反攻的来球只是带有一定的上旋，现在的他在主场面对王励勤时又有所发展，反攻的是上旋更强的弧圈球（即王励勤的抢拉半出台球）两者技术要领相近，但后者难度更大</p><h4 id="第四剑-正手连攻" tabindex="-1">第四剑：正手连攻 <a class="header-anchor" href="#第四剑-正手连攻" aria-label="Permalink to “第四剑：正手连攻”">​</a></h4><p>劈头盖脸就地微调落点严谨</p><p>波尔在与老萨的比赛中，在连续打了萨的两板 正手大角后，波尔又打回其反手位，最终迫使老萨回球下网。类似这种反手发动或拉一板加转后衔接正手“连珠炮”的套路，也是波尔常用的制胜法宝之一，其长处在于：</p><p>速度快 波尔的站位前后移动幅度并不大，始终比较贴近球台，手位也保持的较高，所以他的正手连续进攻由上往下压的较多，往往令对手感到“劈头盖脸”；</p><p>连续好 波尔侧身攻完第一板后，身体重心并不是立刻扑回正手位，而是先呆在原地，因为他的进攻落点较好、质量较高，常能把对方的下一板回球限制在某个区域之内，所以他只需就地微调，即可展开连续进攻，这样对保证进攻的稳定性很有好处。徐寅生主任当年打球时也有这种球，攻完大角度后不会盲目去保正手，而是“守株待兔”，不像一些水平不高的选手，侧完身立刻习惯性扑正手，等球到了中间、反手位再重新侧身，就来不及了。</p><p>落点刁 在比赛中，波 尔一般在完成调正手后盯住机会就会打对方反手，而且连续打两板直至得分，体现出严谨的落点意识和较高的战术素养。很多年轻选手在激烈的拼抢中，一旦出了机会球狠不得一板得分，或者哪里舒服就往哪打。相反，优秀选手被动时会用反手撩住了，有意空着正手位，等你打我正手我就去反拉。其实，很多高水平选手在中远台都有正手反拉的能力，但是反手多半只能托半高球，假如我们战术素养不高，打着反手时看正手好象有空当或者位置还不合适就去打正手，很可能中招被对方正手反拉，这种球失分会令自己元气大伤。波尔在这里给我们上了生动的一课：近台很快调的很开，出了机会死盯反手不放。</p><h4 id="第五剑-发球" tabindex="-1">第五剑：发球 <a class="header-anchor" href="#第五剑-发球" aria-label="Permalink to “第五剑：发球”">​</a></h4><p>二次引拍避实就虚</p><p>有的人是发球前引拍，引完拍后直接摩擦球，波尔却不是，他在抛球时引拍并不大，但在球下落将要触拍的一瞬间，作第二次引拍。由于这种引拍动作小而细腻，连贯性强，加强了挥拍惯性，能把力量真正作用到手腕、手指直至球拍上，所以发球用力集中、出手快、弧线低、隐蔽性强。</p><p>波尔这板发球看似简单，实则精明。马林反手位搓球非常转，所以波尔发到马林正手位，迫使马林用正手搓接，这样就抓住了马林的相对弱点，令其搓球旋转下降，弧线也稍高。</p><p>也就是说，在发球这个环节上，波尔借助自己的发球质量和落点变化，限制了马林的进攻，把马林的回搓控制在了自己的预想的范围内，为随后的进攻做好了准备。</p><h4 id="第六剑-台内争抢" tabindex="-1">第六剑：台内争抢 <a class="header-anchor" href="#第六剑-台内争抢" aria-label="Permalink to “第六剑：台内争抢”">​</a></h4><p>不忘引拍</p><p>波尔技术较为细腻，善于前台争抢，所以发球后不象很多选手那样退的很后、手沉的很低，而是贴近球台，上前挑打时上身几乎趴在台面上。很多人在前后没引拍就直接挑打，结果力量释放不够充分、对球的调节显得僵硬，波尔的高明之处就在于，他先有一个小的引拍动作，再往前打，这是超一流选手的高级细节技术，即使与中国选手相比也毫不逊色。波尔挑打的落点，“定”住了马林的反手，破坏了马林的侧身，形成了波尔主动的局面。</p><p>实际上，在波尔与刘国正的比赛中，也是以手腕的突然转动，快搓刘的国正的正手大角，迫使刘国正拉加转球回斜线、陷于被动。</p><h4 id="第七剑-正反手衔接" tabindex="-1">第七剑：正反手衔接 <a class="header-anchor" href="#第七剑-正反手衔接" aria-label="Permalink to “第七剑：正反手衔接”">​</a></h4><p>波尔抓住马林反手后赢得了主动，令马林的反手“架”了起来。但马林毕竟也是超一流，他深知如果回到波尔正手位，波尔不必移动就可展开连续进攻，自己将更加被动。于是，马林推了一板直线到波尔反手位。按照常理，这种球已是难能可贵，因为大多数选手从正手回反手较慢，然而，波尔的特点恰恰在于：他在近台由正手回反手更快，由反手到正手却相对慢一点。因此，马林这板能克制一般选手的球，波尔却处理的很好，顺势拉了一板到马林正手大角。波尔回反手时，不象很多人是从台面下“捞”上来的，他的反手较高，几乎是横着过来的，拍形的交换也非常迅速。</p><hr><h2 id="第三部分-【其他专家】谈专项技术" tabindex="-1">第三部分：【其他专家】谈专项技术 <a class="header-anchor" href="#第三部分-【其他专家】谈专项技术" aria-label="Permalink to “第三部分：【其他专家】谈专项技术”">​</a></h2><hr><h3 id="【王励勤】谈对付下旋球" tabindex="-1">【王励勤】谈对付下旋球 <a class="header-anchor" href="#【王励勤】谈对付下旋球" aria-label="Permalink to “【王励勤】谈对付下旋球”">​</a></h3><p>对付下旋球，一般都使用弧圈技术。弧圈球又分加转弧圈（又称高吊弧圈）和前冲弧圈。初学者最好先掌握加转弧圈技术，因为它是拉前冲弧圈的基础。加转弧圈球的特点是旋转强，弧线高，球速相对较慢，球在落台后下沉速度快。</p><h4 id="拉加转弧圈的动作要点" tabindex="-1">拉加转弧圈的动作要点 <a class="header-anchor" href="#拉加转弧圈的动作要点" aria-label="Permalink to “拉加转弧圈的动作要点”">​</a></h4><p>准备姿势：两脚左右开立，稍稍大于打球的距离。左脚在前，右脚在后，两膝稍稍弯曲，身体长较低。执拍手沉肩垂臂，引拍至身体后下方，拍面稍前倾，身体重心移至右脚（以右手为例）</p><p>动作要求：大臂带动前臂向前上方挥拍，并逐渐加快挥拍速度。根据对方来球放置程度控制好拍形角度并找准击球的位置和时间。拉球过程中身体重心由右脚向左脚移动。球拍触球时，右脚蹬地，身体向左侧转动。在磨擦球的瞬间迅速收缩前臂。通过手腕和手指加速发力，在来球的下降前期击球的中部或中上部。拉球后，球拍随势挥至头部高度，身体重心移至左脚。拉加转弧圈球时，应该注意腰、髋和腿的力量配合，初学者可以先做徒手动作，然后再上台练习。加转弧圈技术练到一定的熟练程度后，可以逐渐体会拉前冲弧圈动作。前冲弧圈的特点是弧线低，速度快，旋转强，着台后球的冲力大并急剧下沉，杀伤力大，在一定上起到了扣杀作用，是优秀运动员的重要技术。</p><h4 id="拉前冲弧圈的动作要点" tabindex="-1">拉前冲弧圈的动作要点 <a class="header-anchor" href="#拉前冲弧圈的动作要点" aria-label="Permalink to “拉前冲弧圈的动作要点”">​</a></h4><p>引拍向右后方（以右手为例），身体重心比拉加转弧圈球时要稍高一些，球拍与来球同高或稍低于来球。挥拍击球时，身体重心、前臂、手腕应向左前方发力，击球的中部或中上部；击球瞬间前臂和手腕向前磨擦。直拍选手的中指应有一个顶拍的动作，横拍选手的食指应有一个向前甩的动作。击球时间为高点期或上升后期。反冲时，昼不要向后拉手，球拍与来球同高，应善于运用腰、髋和腿的动作，以身体重心来控制击球的弧线。拍形稍前倾，触球时，自己发力和磨擦都比快带多一些。</p><p>拉前冲圈同样要注意身体各个部位的配合。同时要着重注意以下几个问题：一是引拍不能太低，身体重心要稍微高一点，以免拉球出界；第二，要注意磨擦球，不能认为撞球多就可以使球的前冲力大。事实上，撞球过多反面前冲力不大，而弧线不好，旋转也不强。</p><hr><h3 id="【郗恩庭】告诉你发球时应把握的要点" tabindex="-1">【郗恩庭】告诉你发球时应把握的要点 <a class="header-anchor" href="#【郗恩庭】告诉你发球时应把握的要点" aria-label="Permalink to “【郗恩庭】告诉你发球时应把握的要点”">​</a></h3><p>我认为，发球时应把握以下几个要点。</p><p>1、持拍手在触球前要放松，使手腕有较大的灵活性，以发挥前臂、手腕和手指的力量，加快球拍碰球时的摆速。如果握拍太深、太死，就不利于发挥手腕的灵活性，这样摩擦球就不能充分。</p><p>2、引拍时，手臂与身体要拉开一些，不要靠得很紧，使整个发球动作舒展些，以便充分发力摩擦球。</p><p>3、击球位置也是有讲究的。在球下降的不同时刻击球，发出球的效果也不一样。我在练习发球时体会到，击球位置总有一个最佳点。在这点触球。便能产生最大的合力，这个位置随每个人的身高、力量和发球动作的不同而有所区别，但一般在腰部位置上下。只要能”吃”住球就行了。每个人多练习，多体会，才能把握其规律。</p><p>4、击球部位。一组好的发球，不仅要求上旋、下旋或不转球之间的差距要大而且发球动作要近似。要做到这一点，就要在击球部位上做文章，因为击球部位相近，发球动作就可以类似，这样发出不同旋转性质的球，效果就好。所以。要尽量在球同一部位的左、右或上、下接触球，并发出不同旋转性质的球。这样的发球就容易迷惑对方。如果发上旋时击球上部，发下旋时击球下部就很容易被对方识破。</p><p>一般来说，发不同旋转的球，接触球的中后部附近比较理想。练习发转与不转球时，先在中部左右触球发出转球，直到基本掌握为止，然后练习在同一部位触球发不转球，如触球时推或裹球等。待球出手的一刹那，作出发转球的随后动作。动作熟练以后，再进一步提高要求，如在”吃”球程度、击球声音和发力的动作等方面不要有明显差别，以增加对方判断的难度，发侧上、下旋球时，都需要摩擦球，摩擦部位也在球的中后部附近，只是触球瞬间，动作一个往侧或往上勾，一个往下切，随后动作要力求近似。</p><p>5、球拍接触球时，应注意两条：一是发力、二是摩擦。其中，发力更为重要，光有 摩擦而没有足够的爆发力。是发不出高质量球的，当然光有力量而缺少摩擦，球的旋转程度就差。</p><p>6、发球时出手动作一定要快。因为发不同旋转球，不管动作如何近似，总还是不一样。如果出手较快，即使对方意识到有点不同，但心里会犹豫。这样，在接发球时就不会很从容。</p><p>7、发上旋时，球的弧线要低。这样与下旋球的弧线接近，既能迷惑对方，又能限制对方进攻。对方一旦察觉来球是上旋，由于弧线低，进攻起来也不容易。</p><p>8、发球时，身体、前臂、手腕和手指要协调配合，使发球动作既稳定又放松，发球的第一落点要准确、稳定。如发长球第一落点要靠近端线。发球力量要大；放松是为了最大限度地发挥手腕的灵活性，以加强对球的摩擦。有些运动员不敢用大力去发球，怕球发出界，其实不必有此顾虑。只要第一落点稳定，用力去摩擦球，就不易出现这种情况。另外，在手臂向后引拍时，最好配合身体重心向后移动，向前挥拍击球时，身体也随之前移，并在移动过程中加速挥拍击球。</p><p>9、要想提高发球质量，还应注重手臂力量的训练，提高手臂的爆发力。上文中所述都是些技巧性的内容，而手臂肌肉力量是实的东西，因此，要加强训练。一般来说，做些引体向上、俯卧撑和跳绳等，对于发展手臂力量是有好处的。此外，还有一些其它的办法能提高手臂肌肉力量。如以前我曾做过一个握力橡胶圈，弹性很大，握一会儿，前臂及手腕、手指的有关肌肉群就累了，天天练习，将有助于提高手腕、手指小肌群的力量，陈龙灿也采用过这种训练方法来加强手腕、手指的力量。再如，在哑铃上拴一根绳，绳上系一根很长的木棒，然后双手转动哑铃，通过绳子在哑铃上的缠绕，把木棒提上来，然后，再做反向动作，把木棒放下去。放时，手腕做伸的动作，更累。这样做上几组，手就酸胀得很厉害，但效果很好。</p><p>10、手腕柔韧性的好与差对于发球也是很重要的。以前我常做一些手腕柔韧性练习，以致手腕做伸的动作时与前臂的夹角可以小于90度。由于手腕的柔韧性较好，因此在发球时，手腕摆幅大，发力足。</p><p>11、发转不转最好还是用摩擦球拍的不同部位来发（摩擦下部越靠近拍沿越转的下旋，摩擦球拍上部则发出不转），靠推或裹来发出不转如果不结合遮挡的话太容易判断了，而遮挡发球现在已经不允许了请问上旋或侧上旋球怎么发？直拍的反向摩擦有哪些动作技术要领？</p><p>12、上旋或侧上旋是在发球时接触球的瞬间收腕向上引拍，摩擦球的中上部。</p><p>直拍的反向摩擦实际上就是用正手发出反手的发球，动作技术要领和正旋转基本一样的主要是一个适应的过程。</p><p>现在比较流行的内旋球发侧上侧下的一个好处就是如果你只要控制好了手型（尤其是手腕）配合着腰自然就能发出相对隐蔽的侧上侧下，不用象传统的外旋那样相对要刻意的手腕向上向下引拍来制造侧上侧下。</p><hr><h3 id="【马凯旋】防守弧圈球——重心为干-技巧为枝" tabindex="-1">【马凯旋】防守弧圈球——重心为干，技巧为枝 <a class="header-anchor" href="#【马凯旋】防守弧圈球——重心为干-技巧为枝" aria-label="Permalink to “【马凯旋】防守弧圈球——重心为干，技巧为枝”">​</a></h3><p>业余选手的攻防转换能力是比赛中得分的重要手段，与专业运动员相比，业余选手在意识和基本技术上还存在很多不足。随着弧圈球技术的发展，防守弧圈球技术是必须要掌握的重要技术之一。中国的弧圈球技术起步相对较晚，陈志斌是第一个两面弧圈打法的优秀运动员，随后中国弧圈球技术逐渐进入了一个鼎盛的时期。从打法上看，目前使用颗粒胶皮的纯快攻选手少之又少，几乎都是反胶的夭下，由于年龄和经历的原因，年轻的业余选手从打球的思路上比较符合乒乓球技术的发展，而一些年纪稍大的业余爱好者对于弧圈球的理解还存在一些偏差。乒乓球的任何一项技术都不能孤立起来看，都有基本理论作为支撑，都是一个延续的过程。</p><h4 id="正手平挡弧圈球" tabindex="-1">正手平挡弧圈球 <a class="header-anchor" href="#正手平挡弧圈球" aria-label="Permalink to “正手平挡弧圈球”">​</a></h4><ul><li>直板打法的选手，无论使用什么胶皮，其基本的技术动作都有一个总体的基础。对于业余选手来说，练习防弧圈球的技术可以从近台平挡开始。在近台用正手平挡弧圈有几个关键问题需要解决：</li></ul><p>第一，基本站位要恰当。平挡弧圈球的时候，站位要比普通正手攻球离台的距离稍远，身体重心要高一些，腿的弯曲程度没有那么大，两脚的间距相对窄一些，这样的站位方式有一种居高临下的感觉，有利于对球的控制。</p><p>第二，握拍要自然。直板的握拍变化较多，但原则是要放松，不能僵硬，否则会影响击球时的感觉。防守弧圈球时，拍形要稍微下压一些，食指不能太用力，拇指略微用力下压，中指很关键，可以用来控制回球的方向。</p><p>第三，用腰部力最顶住来球。合理运用腰部是接弧圈的一个重要的环节，无论直板还是横板，找到用腰的感觉比找到用手的感觉还要重要，通过身体重心和腰形成转动式的挡球动作，利用腰的转劫完成引拍过程。转腰的时候，腰右侧的髋关节以及膝盖和脚都要有迎前的感觉，要同步地转动，这样有利于手臂的放松。防守弧圈球的实质是通过身体重心的交换来打球，有了重心交换，脚下才能有“根”，才能站得住，才能够连续地衔接。如果没有重心交换，脚下就无法蹬住地，就无法快速移动。击球前，要将身体重心提高，通过腰部的转动带动前臂，手臂必须充分放松，不能把肩架起来接弧圈，否则会导致身体的僵硬。</p><p>第四，减小引拍拉手的幅度。防弧圈的时候，通过腰部小幅度地转动，带动手臂向后引拍，尽量不要拉后手，否则很容易被来球顶住，造成身后击球的状况，因此防守弧圈球时的击球点一定要在身前，要学会追着球打。</p><p>第五，在来球的上升后期击球。防守弧圈球时，击球的时间一般比普通正手攻球要早，要在来球的上升后期击球，这样更容易借到对方来球的力量。对于业余爱好者，在练习正手平挡弧圈的时候可以适当延后击球时间，在来球的最高点击球，在最高点击球更容易找到控制球的感觉，在击球前可以有充分的时间来调整站位和调节拍形。怎样才能找到最准确的击球点呢？业余选手在练习的过程中总会遇到这样的问题。很多选乎防守时容易过早地击球，很容易回球下网。要想找到准确的击球点就必须要提前判断对方来球的弧线长度，要及时移动步法，这样才能找到最佳的击球点。</p><ul><li>横板正手挡弧圈的技术与直板大同小异。与直板技术的不同在于：</li></ul><p>第一，横板的拍形控制比较容易，因为横板的握拍更加稳定，这样有利于对回球的控制。</p><p>第二，横板在防弧圈的过程中，食指的作用很大，通过食指的下压，可以更精确地感受到来球的旋转强度和力度，起到控制回球弧线的作用。</p><h4 id="正手反带、反剃弧圈球" tabindex="-1">正手反带、反剃弧圈球 <a class="header-anchor" href="#正手反带、反剃弧圈球" aria-label="Permalink to “正手反带、反剃弧圈球”">​</a></h4><p>平挡弧圈球是防守弧圈球技术的基础，掌握这项技术可以加深对弧圈球的认识，并了解防守弧圈球的基本原理。当平挡弧圈球有了较深的感觉之后，我们可以在练习中逐渐加入一些新的元素，例如在触球的瞬间，前臂收缩突然加速，直板选手的中指或横板选手的食指稍微加一些力量，腰在接触球的时候突然转动，对来球加一点摩擦，这就是我们通常所说的反带弧圈球。反带弧圈球是一项近台技术，通常是在对方拉球力量不太大的情况下使用。如果说平挡弧圈球纯粹为借力回球，那么反带弧圈球主动发力的成分相对多一些。反带弧圈球更加强调腰部和身体重心转换的运用，由于反带弧圈球的技术动作比平挡弧圈球稍大，那么保持身体的平衡至关重要。我们可以从刘国梁的技术中找到反带弧圈球的灵感，刘国梁在正手反带的时候都是用腰来挡球，无论击球的动作幅度有多大，手背总是以腰部为中轴，利用腰部的转动来控制回球，虽然刘国梁在防守的过程中还有很多的动作的变化，但所有的技巧都是从这个根基延伸而来的。</p><p>当对方来球不太“冲”的情况下，反带时，腰部转动的幅度要大一些，前臂向前运行的行程更多一些。接触球的瞬间，拍形可以适当下压，直板选手的中指可以加力顶一下球拍，摩擦来球的中上部，前臂收缩突然加速，需要注意的是：击球时，大臂不要离身体太远，否则肩部会架起来，容易导致动作变形，使手臂和身体脱节，这样就无法发力，无法很好地控制球；球拍与球的高度几乎处于同一水平线上，这样才可以保证找到最佳的击球点，才可以释放更多的爆发力，增加回球的稳定性和威胁性。</p><p>反剃是防弧圈球的重要手段，这项技术建立在反带弧圈球的基础上。反剃弧圈球与反带有一定区别：反带对球的摩擦相对少一些，反剃发力的成分多一些。反剃时，前臂收缩要快，动作更加紧凑，在借力中要学会加力。击球时，腰部的转动幅度更大，转动速度更快，前臂收缩更快。反剃弧圈球的击球点一般在来球的上升后期，引拍时一定耍注意用腰带手，不能向后拉手。虽然反剃的威胁很大，但对方回球的速度也会相应提高，因此反剃时身体的重心要平稳，这样才可以迅速还原，保证下一板球的衔接。</p><p>无论是反带还是反剃，横板选手与直板选手的技术要领基本一致，但由于握拍的原因，横板选手的手腕运用受到了一定限制，因此在回球的线路控制上具有更高的难度。防弧圈球要注重落点的变化，如果是回直线球的话，那么拍形要更接近于球体的纵轴中心线：如果是回斜线，那么拍形要稍微偏向球的纵轴中心线右侧，这样才可以“包”住球。业余选手在练习的过程中，同样可以采用多球的训练方法来体会回球的技巧，还可以让对方在正正手位和侧身位分别拉球来练习防守弧圈球线路的变化。</p><h4 id="正手反拉弧圈球" tabindex="-1">正手反拉弧圈球 <a class="header-anchor" href="#正手反拉弧圈球" aria-label="Permalink to “正手反拉弧圈球”">​</a></h4><p>反拉弧圈球是防守转攻的强势技术，多在中台位置回球，专业运动员还可以在近台反拉弧圈球，这项技术具有很高的难度。很多业余选手在练习中急于求成，见到对方拉球就想反拉，但是在中台回球对步法和身体协调性提出了更高的要求。近台技术几乎都是借力的成分大于自身发力的成分，而反拉在自身发力的成分会更多一些。反拉的难度更大，大臂和腰要充分运用。业余选手在练习中台反拉弧圈球的时候可以在来球的最高点击球。反拉时，双脚的间距较宽，要根据来球的弧线高度调整身体重心的高度，以腰带动手臂向后引拍，击球时，腰部转动的幅度较大，大臂要随腰部的转动伸展出去，这样才可以充分发力。反拉时需要注意：出手要果断，击球点必须要准确，不要过多强调前臂的收缩，而更应该运用大臂，腿要用力蹬地，把身体的力量充分释放，将球的弧线拉长。</p><h4 id="反手推、挡弧圈球" tabindex="-1">反手推、挡弧圈球 <a class="header-anchor" href="#反手推、挡弧圈球" aria-label="Permalink to “反手推、挡弧圈球”">​</a></h4><p>直板选手的反手技术有很多技巧，无论是传统的推档还是横打，在防守弧圈球的环节都具有各自的优势和特点。很多业余选手在推弧圈球的时候，出于对弧圈球的恐惧，通常站位会离球台太近，反手推挡首先要解决的问题就是不要让来球把自己顶住，因此推弧圈球的时候，站位要略微离台远一点。击球时，要敢于把手伸出去，一般来说直板反手推挡最佳的发力点是前臂向前伸展将近一个前臂的距离。推弧圈球的要领在于要能够借来球的力量，还要为自己的发力创造足够的空间，业余选手练习的初期可以通过多球的方式训练，先让对方拉一些长球、旋转不太强的球，这种方式可以有效地改善自身的站位。</p><p>推弧圈球时要注意腰的运用，尤其是发力推的时候要加快腰部的转动速度以及前臂伸展的速度。减力挡一般在对方来球不长，力量不大的情况下使用，可以有效地遏制对方的连续进攻。当对方来球的力量较大时，使用减力挡有不小的难度，这对手上的控制能力有更高的要求。减力挡的时候要靠腰部作为支撑，身体迎前，在来球的上升后期击球，靠身体的重心交换和手臂的调节卸掉对方来球的力量。纯粹的减力挡要找到准确的击球点，击球的一瞬间前臂向怀中略微内收，起到一个缓冲的作用，将来球的力量卸掉。业余爱好者在练习时要将身体充分放松，手臂贴近身体，前臂自然向前放。引拍时重心放于右脚，通过腰部的转动带动手臂，出手的同时，同样要转动腰部，前臂水平伸展迎球，这样才可以找到最佳的击球点，提高回球的稳定性。</p><p>对于直板选手来说，普通的推挡与推弧圈球有一些区别：推弧圈球的动作更加紧凑、小巧，前臂伸展的幅度较小，借力的成分更多一些。而普通推挡的时候，动作幅度可以大一些，手臂向前送的更多一些，要多向前迎球。横板选手的反手平挡弧圈球技术与直板推弧圈球技术大致相同，反手平挡强调腰的运用，要依靠腰部的力量顶住来球，在出手的瞬间腰部要有一个小幅度的转动：还原时，要将重心放于右脚上。</p><p>随着直板横打技术的出现，在防守弧圈球的技术上又有了新的选择，但直板横打技术比较新，业余选手掌握起来有一定难度。横打通常在进攻环节有一定威胁，相对防守技术，我们可以先练习平挡，与反手推档技术相似，反面平档也要在身前击球，要迎前，在来球上升后期击球。横打的握拍很关键，手腕要向怀中内收一些，这样的动作才可以将拍形调整到最佳的角度。</p><h4 id="反手侧挤弧圈球" tabindex="-1">反手侧挤弧圈球 <a class="header-anchor" href="#反手侧挤弧圈球" aria-label="Permalink to “反手侧挤弧圈球”">​</a></h4><p>反手侧挤是直板选手防守弧圈球的一项重要技术，具有很强的技巧性。侧挤是从身体右侧向左斜前方发力，接触球体的纵轴中心线偏左的位置。侧挤利用了改变击球的旋转轴来改变回球的旋转，同时改变击球的旋转轴可以有效卸掉来球的力量，改变回球的节奏。侧挤带有一定的侧旋，这种回球方式可以增大回球的角度，给对方造成更大的威胁。侧挤要求动作一定要紧凑，手臂与身体成为一个整体，依靠身体来控制回球的动作，提高回球的稳定性。业余爱好者在练习侧挤时，也可以像练习推弧圈球一样，进行加、减力的练习。</p><h4 id="反手快撕弧圈球" tabindex="-1">反手快撕弧圈球 <a class="header-anchor" href="#反手快撕弧圈球" aria-label="Permalink to “反手快撕弧圈球”">​</a></h4><p>横板的反手技术要比直板容易一些，当掌握了反手平挡弧圈球之后，就可以练习反手快撕技术。反手快撕的技术动作很自然，更容易掌握。反手平挡和快撕在腰部的运用上有一些变化：快撕不像反手拉球那样水平转动腹部，此时腰部几乎是前后运动，更多地使用腹部的力量。业余爱好者在体会到快撕的感觉之后可以适当练习加力撕。发力时，用拇指和手背来控制拍形，在击球的瞬间带有一些摩擦，改变回球的弧线长度和速度。反手加力快撕时需要注意：引拍时，要减小动作幅度，否则很容易被来球顶住。击球时，肘部不能翻动，要有撑住手臂的感觉，否则将无法控制来球；拍形不要压得过低，在来球的上升后期击球，发力方向一定向右斜前方，要充分利用身体重心交换和前臂的动作加强对球的摩擦，增大回球的力量，增强回球的旋转，针对直板横打的选手也可以进一步练习快撕技术。快撕时，要注意手腕不能太灵活，要相对稳定，拇指用用力下压，这点跟横板的反手技术有一些相似。横打反撕的用力方向也是向右前方，但横打不如横板的反手那样易于发力，这是练习过程中的难点，掌握好拇指和食指的运用是控制拍形和发力的关键。</p><p>乒乓球技术还在不断发展，防守弧圈球技术的运用也越来越灵活。无论是直板还是横板打法，在正手防弧圈球时借鉴了反手技术中减力档的动作要领，通过腰和前臂的小动作将来球的力量化解，使回球的弧线变低、变短，瞬间改变了回球的节奏。还有正手反带侧旋球，在防守弧圈球的时候接触来球的侧部，使回球的旋转发生改变，这些变化都是目前乒乓球技术的特点。</p><p>所有的防弧圈技术都要先能借上来球的力量，都要找到最佳的击球点，这样才可以提高回球的质量，保证回球的稳定性。所有的技术都要以腰为中心，用腰带手完成每个击球的环节，掌握了这些要点就掌握了防守弧圈球的基本原理。</p><hr><h3 id="【肖战】正手近台对付弧圈球的-反带-、-反拉-技术" tabindex="-1">【肖战】正手近台对付弧圈球的&quot;反带&quot;、&quot;反拉&quot;技术 <a class="header-anchor" href="#【肖战】正手近台对付弧圈球的-反带-、-反拉-技术" aria-label="Permalink to “【肖战】正手近台对付弧圈球的&quot;反带&quot;、&quot;反拉&quot;技术”">​</a></h3><p>弧圈球的正手位近台的反带、反拉技术起源于八十年代初期，中国的直板弧圈球运动员郭跃华首先掌握运用此项技术，发展到九十年代中国的孔令辉，法国的盖亭.比利时的塞费都进一步发展了反带、反拉技术。而我们国家很多弧圈球运动员正手位近台常常去“挡”球，或是退半步，甚至退一步去对拉，其结果，挡过去的球不具有威胁，很难摆脱被动局面，而退半步去对拉，反手位更易陷入被动，特别是直板弧圈球选手，推挡失去作用，既使能直拍横打，反手退台也能拉，但力量不大，速度不快。所以只能坚持正手位近台对付弧圈球运用反带、反拉技术才符合乒乓球发展到2000年它的趋势越来越向近台，凶狠，积极主动进攻方向发展。当今法国的盖亭等运动员体现了这种趋势。要快还必须坚持在近台，要积极主动也必须坚持在近台，所以弧圈球运动员在正手位对付弧圈球必须坚持近台反带、反拉，所谓“反带”、“反拉”的函义在于对方拉出低弧线前冲力很强的弧圈时，一般运用反带技术，就是利用借助对方强有力旋转，手臂相对固定用腰部转动稍加手腕力量加以磨擦，过去的球带前冲力，而且比较稳定，反带既不是防守技术，也不是完全的进步技术而是两者之间的技术，比正手挡球威胁更大，容易在被动中转为主动。当对方拉出的弧圈球弧线稍高，就运用反拉技术，这是完全的进攻技术，比反带技术动作稍大，同时腰部动作也稍大些，也要善于借助对方的旋转。2000年的弧圈球运动员正手近台对付弧圈球必须坚持在近台反带，反拉弧圈，从打法上更能积极主动，只有掌握搏杀技术，才能有搏杀能力，符合2000年乒乓球的发展趋势。就“反带”、“反拉”技术要领及训练方法体会如下：</p><h4 id="近台反拉动作要领" tabindex="-1">近台反拉动作要领 <a class="header-anchor" href="#近台反拉动作要领" aria-label="Permalink to “近台反拉动作要领”">​</a></h4><p>正手反拉是在近台对攻基础上发展起来的，故与正手攻球动作有相似之处，近台反拉的用途--对付弧线稍高的前冲弧圈球。</p><p>1、准备阶段：</p><p>要求站位近台，距球台端线大约半米左右。右脚偏后，双脚之间的距离稍比肩宽，两膝微屈，脚掌着地。大臂与前臂的角度一般保持在90度左右，收腹，身体保持前倾，拍形与面呈现60度左右，球拍稍高于台面。</p><p>2、击球阶段：</p><p>弧圈球渐近身前，手臂后摆引拍至肩宽，小臂自然放松和大臂呈现120度左右。</p><p>大臂带动前臂向前，将触球，手腕稍内旋，拍形和台面呈现30度-40度，掌握往来球的上升期。触球体侧，上中部，手腕同时向上，向前发力磨擦，将来球反拉出手。与此同时，腰部向左侧转动。重心移到左脚。</p><p>3、需注意的几点：</p><p>（1）身体一定要保持前倾，关键是收腹。因此位近台，收腹后将使身体距球台空间增大。手臂向前挥动幅度可稍加大。便于磨擦球体，帮助制造弧线，也利于腰部肌肉协调配合发力。</p><p>（2）击球时不能倒肘，往往在近台，也想发力，往往就倒肘，当肘关节高于前臂后，球的命中率就大大下降。如果肘部高于前臂后，拍形和台面呈现0度，会导致拉空和下滑。因反拉时本身拍形前倾角度就小，所以一定不能倒肘。</p><p>（3）反拉时应用并步为宜，重心稳定，膝，腰协调转动可帮助制造弧线，增加球的前冲能力。</p><p>（4）拍形要前倾固定，出手角度要小，直板选手触球瞬间要集中大拇指和台面三个指头向上，向前爆发力量。横板选手食指要向前用力，大拇指要调节用力。</p><p>（5）后摆引拍不宜过大，后摆动作幅度大不易控制来球，而对方的弧圈速度快，容易造成球 “撞扳”现象，只有板主动、快速磨擦球体才能控制住来球。</p><h4 id="反带技术动作要领" tabindex="-1">反带技术动作要领 <a class="header-anchor" href="#反带技术动作要领" aria-label="Permalink to “反带技术动作要领”">​</a></h4><p>近台反带技术的用途--对付低弧线前冲力很强的弧圈球。反带动作和反拉动作基本相似，不同之处是由于前冲弧圈球速度快，弧线低，所以反带时手臂后摆引扳动作幅度比拉要小，上臂带动前臂向前，触球时手腕向前发力磨擦。击球关键是拍形前倾固定，触球时以上臂，手腕向前发力为主，前臂起辅助作用。</p><h4 id="训练方法" tabindex="-1">训练方法 <a class="header-anchor" href="#训练方法" aria-label="Permalink to “训练方法”">​</a></h4><p>1、（供球）多球训练：</p><p>（1）教练员可连续供出定点高吊弧圈，练习者连续训练反拉动作。</p><p>（2）教练供出定点前冲弧圈，练习者连续训练反带动作。通过反复多练逐步形成自动化条件反射，达到“动力定型”。</p><p>（3）在动作基本熟练的基础上教练员可把球供去1/2球台逐步扩大到2/3球台，让练习者在移动中进行练习。</p><p>2、三人多球练习方法：</p><p>（1）教练员站在练习者一方靠近球网的左方，连续供出搓球，对方连续拉高吊弧圈或前冲弧圈，练习者反复训练反拉和反带技术。</p><p>（2）多球定点双线练习，教练员供出搓球后，对方先拉直线连续拉斜线练习者反手挡、拨，正手反拉或反带。</p><p>（3）多球不定点双线练习，当教练员供出球后对方拉出不定点的弧圈球，弧线稍高就反拉，前冲低弧线就反带。</p><p>（4）发球后在左半台进行反拉，练习者发出刚为出台的下旋球队，对方拉高昂或低弧线前冲，练习者从左半台用并步，移动到右半台去反带，反拉。</p><p>3、单球对练训练方法：</p><p>（1）开始对练正手反带、反拉，可用单线为主，要求对手在中近台连续拉出弧圈，练习者在近台根据来球性质正确判断后，进行反带，反拉练习。</p><p>（2）双线定点练习，左推（拨）右反拉、反带。</p><p>（3）双线不定点练习。</p><p>（4）发球后，对方拉出不同落点的弧圈练习者在移动中进行反拉。</p><hr><h2 id="第四部分-【补充内容】伤病预防与基础概念" tabindex="-1">第四部分：【补充内容】伤病预防与基础概念 <a class="header-anchor" href="#第四部分-【补充内容】伤病预防与基础概念" aria-label="Permalink to “第四部分：【补充内容】伤病预防与基础概念”">​</a></h2><hr><h3 id="【队医厉彦虎】谈-乒乓职业病-及预防" tabindex="-1">【队医厉彦虎】谈&quot;乒乓职业病&quot;及预防 <a class="header-anchor" href="#【队医厉彦虎】谈-乒乓职业病-及预防" aria-label="Permalink to “【队医厉彦虎】谈&quot;乒乓职业病&quot;及预防”">​</a></h3><p>作为一个老运动员，孔令辉有许多伤病是众所周知的，他的运动生涯会因此而受到影响吗？</p><p>目前的伤病对他的运动生涯没有太大的影响。他的颈椎有些问题，背部也不太好（背部关节劳损），但通过每天的按摩调理，基本不会影响他的训练。他的腰是有点伤，但现在还比较稳定，踝关节有创伤性的骨关节病，也有骨质增生。而他的肩伤是反复的陈旧伤，所以大运动量训练时肌肉和韧带疲劳后会有些牵拉，但问题不大。经过长期的运动生涯之后，运动员的关节多多少少都会有些伤，某些队员十几种病都有可能说得出来。</p><p>马琳的情况如何？</p><p>马琳身上的伤很多，比如说颈椎的问题是职业运动员所共有的，因为他们经常要甩脖子，颈椎关节受到剪力作用。马琳的颈椎问题，主要在于他两肩的神经特别紧张。运动员都有骨刺增生的情况，而马琳的双肩就有点骨刺，所以会特别紧。他有时肩疼，光治肩是不行的，颈椎是一个根本的问题。我已经掌握了他的规律，只要他一说肩疼，我就给他治颈椎，很快就好。至于他的腰部，主要是存在疲劳性骨折，当然这种现象其他运动员也有。为什么会疲劳性骨折呢？因为马琳在做动作时幅度特别大，由于关节的限制，转不了那么大的角度，而长期腰椎在剪力作用下，骨质受到不断破坏，形成疲劳性骨折。起初特别疼，后来他已渐渐适应，骨头已经磨得适应了，现在已经不怎么疼了。</p><p>一般来说乒乓球运动员有哪些职业病呢？</p><p>比如腱鞘炎、颈椎病、骨刺增生，还有膝关节末端病、软骨损伤、颈骺炎等等。小运动员尤其容易出现问题，因为正处在长身体的时候，肌肉韧带还没有长好，力量不够，来回跑动急停很容易受伤，应特别关注长身体时的脊柱侧弯问题，训练后反向牵拉，平衡力量训练十分重要。</p><p>那这些职业病在退役之后会不会好起来呢？</p><p>退役以后也好不了。如果没有做剧烈运动，情况会缓解一些，但稍微运动量大一点，或者遇到阴天，就会有影响。运动创伤，特别是慢性的运动创伤，一遇阴天就会有反应，病理与风湿性关节炎反应类似。</p><p>听说运动员最怕站军姿？</p><p>是啊，队员就怕站着不能动，那对他们来说是非常痛苦的事情。由于长期做单面运动，会造成脊柱不正，时间长了，骨头也会出现问题，而军姿要求站得特别正，所以他们周身难受，稍微斜一点就会舒服些。运动员的双肩也有很多是畸形的，比如说看他们裸着肩时，就可以发现两个肩不一样高，一边特别发达，一边差很多。两条胳膊也是，就好像不属于一个人似的。所以我一直都反复强调他们要做平衡力量，平衡就是两边一起做，如果双手握拍就好了（笑话），当然打球中这是不可能的，因为有职业的要求，但身体力量训练就要强调平衡。</p><p>对业余爱好者来说，打球时应采取哪些预防措施呢？</p><p>首先，训练之前一定要做好准备活动，一般队员要做20分钟左右，包括慢跑、关节的旋转及各个角度的牵拉，做做热身操也不错，没有预热不可以进行运动。我就见过好几个球迷，他们都不做预热，一看到有球台特别高兴，上去就打，有时打久了都打出骨刺。其次，打球时不要单面运动，比如单面的发力拉冲，总是一个角度，老打正手或是反手，这是不平衡的运动，肯定会出现问题。此外，通常半小时为一节比较好，休息一会缓一缓，但在缓的时候不能歇着，而应稍微走一走。咱们队员一般是两个小时休息一下，但他们的准备活动做得比较充分。</p><hr><h3 id="【庄则栋】谈基本功训练——什么是原地步法" tabindex="-1">【庄则栋】谈基本功训练——什么是原地步法？ <a class="header-anchor" href="#【庄则栋】谈基本功训练——什么是原地步法" aria-label="Permalink to “【庄则栋】谈基本功训练——什么是原地步法？”">​</a></h3><p>步法与重心的关系</p><p>移动步法首先是移动重心。支撑重心的这只腿可以做蹬、踏、跳跃动作，却不便于做移步动作；不支撑重心的这只腿脚，可以做抬步动作，却不能做蹬踏动作。在乒乓球运动的此起彼落的快速运行中，重心的变换是步法的核心。重心交换得快则轻松，敏捷导致着步法的灵活、准确、快速，因此，不注重重心交换的运动员步法是不会好的。</p><p>1．什么是原地步法</p><p>就是腿和脚不向前、后、左、右跨出去，只在原地进行着快速、轻松而又时刻准备着发力的左、右脚重心的交换。</p><p>2．原地步法训练的目的是什么？</p><p>（1）这是初学打乒乓球时掌握步法要领，打好步法基础的基本功训练。</p><p>（2）只有掌握了原地步法训练的基本功才能为今后步法的迅速起动、连续跑动打下坚定的基础，也只是掌握了这种基础步法才能向更复杂、更高深的步法境界去进军。</p><p>（3）培养手法、腰腹、躯干、髋骨、腿部肌肉群等方面与步法的协调、灵敏的有机配合。</p><p>3．对原地步法训练的要求</p><p>（1）准备姿势（以正手近台斜线攻球、右手握板者为例）</p><p>身体站离球台约50公分，站于中线偏左一点，大臂靠近身体，小臂向前和大臂约成90度角，左臂也略抬架起来，两脚开立，左脚稍前，右脚稍后，两脚间的距离多一肩半至两肩宽，提踵离开地面约二寸至三寸（但不要把脚后跟提到极限，以防肌肉过分紧张僵硬），前脚掌的内侧着地，双膝弯曲，膝关节略向内收，躯干挺立，含胸收腹，上肢略向前倾，两脚不停地小幅度、小动作地交换着重心。</p><p>（2）重心交换</p><p>步法的核心技术是重心交换。通过原地步法的训练，首先把重心交换的技术掌握好，每攻一次球，身体重心交换一次，重心交换的关键技术是腰、腹、髋、腿、脚协调一致性的前后转动，更重要的是腰、腹、髋发力带动与上肢及腿部、脚有机而密切的配合。击球前，左脚内旋，右脚外旋，腰髋向后转动，重心移至右脚。击球时，右脚内旋，左脚外旋，腰髋用力向前转动，重心则移至左脚，击球之后，力求迅速还原。</p><p>（3）加强蹬地力的训练</p><p>用脚蹬地面的作用力，会使地面对脚产生力量大小相等，方向相反的反作用力。由此可知，脚对地的蹬踏力是步法的基础力量，这个蹬踏力的运用和准备应该在原地步法的训练中熟悉、掌握，其战略性意义是很深远的，如：</p><p>①当出现了机会球，运用杀手锏，打算一板子砸死对方时，如果没有对地面强有力的蹬踏力是不会杀出很重的板。</p><p>②在连续进攻中，人体运行完全依靠步法，如果没有足够的蹬踏力量，步法移动的速度则不会快，而连续进攻会必然脱节失误。</p><p>③在搏斗中出现步法凌乱，重心不稳，这也反映出步法的协调性、灵敏性、柔韧性差。究其原因，也和蹬踏力的基础不好有着密切的关系。</p><p>（4）掌握蹬踏的技巧</p><p>①蹬与旋的结合</p><p>蹬地与脚掌旋转起动是连续在一起的动作，所以，蹬与旋要紧密地结合。</p><p>②掌握刹车</p><p>击球之前右脚蹬地起动，重心转移至左脚；左脚也要相应恰当地用力蹬地，这样，左脚蹬地，产生的反作用力就象刹车一样，使身体导致相对的平衡。否则，随着身体由右脚蹬踏力量的惯性人会跌倒。左脚的刹车不仅能使身体保持平衡，也为迅速还原和为下一板的进攻做好准备。</p><p>4．训练方法</p><p>（1）内容：正手斜线对攻，侧身斜线对攻，攻挡，然后交换进行。要求击球的力量发力轻匀（约在全力的20％左右），而击球的命中率则要求每球击50回合之上，因为训练的侧重点在于步法的训练。</p><p>（2）特点：上肢击球动作要求小而力量轻，用近台正手快攻，以前臂击球为主，动作幅度不宜过大，要求躯干、腰腹转动的幅度要小，脚的内外旋幅度也要小，攻球时注意好脚、腿、腰的起动，加速和制动的配合运用。上肢动作轻小，对下肢的稳定、平衡很有利，这样便于对下肢动作侧重地、针对性地去进行训练。</p><hr><h3 id="【基础教学】新手上路——搓球练习路径" tabindex="-1">【基础教学】新手上路——搓球练习路径 <a class="header-anchor" href="#【基础教学】新手上路——搓球练习路径" aria-label="Permalink to “【基础教学】新手上路——搓球练习路径”">​</a></h3><p>1 引拍</p><p>初学者要掌握的搓球最主要的环节，就是看见球要引拍。使用进攻性技术时，引拍、挥拍大家比较好理解，可现在电视媒体这么发达，中国人又有福气，看到的都是顶尖高手打球，一看高手好像手搁那儿没引拍球就搓过去了。可是，你要知道他或许是练了十年才形成那样的动作，他刚一开始练球也是一板一眼搓过去的。上个世纪五、六十年代的运动员都知道，搓球有个别名叫“小削球”，原因就在于它要引拍，像削球一样。假如没有引拍的动作，没有充分练习过慢搓，无论直横拍，你都不容易加转，因为刚开始打球的时候手腕手指的配合还不能掌握得很自如，就模仿高手在手臂几乎伸直的情况下“捅”着搓，这样既没控制，旋转也没变化，下面的接发球更连谈都不要谈。</p><p>2 缓冲</p><p>搓球跟攻击性技术最大的区别，就在于摩擦加转时要有缓冲，要有“送”的感觉，大臂要跟着前臂送出去，这样搓出去的球你才能有控制。要自己能感觉到“吃”住球，球在球拍上停留的时间够长。以直拍为例，食指和中指在“送”的过程中，你完完全全能感觉到制造下旋的摩擦，它不是紧急制动的那种摩擦，而是要跟进一定的长度。你搓出去的球不是像炮弹“当”地一下撞出去的，而是有摩擦有缓冲的，是“软中硬”的，这样才具备了搓球的基本要素。缓冲与引拍也有关系，要求引拍时学会放松，尤其在练习搓球的过程中，由于球速慢，你能比练习攻球更好地学会放松。假如没有缓冲，直接练“捅”着搓，开始看着也许还行，一过初级阶段，碰上中级对手了，你接发球不是“冒”就是“吃”。</p><p>3 节奏</p><p>很多时候，初学者知道要引拍了，可是掌握不好挥拍的节奏，往往不是慢的多，而是早的多，节奏太快。这是因为在搓球之前练的是攻球，是上旋球的节奏感觉，于是球还没到，拍已经挥了，有效的动作根本没用上。这时候，就要盯球，只有根据对方回球的速度来决定你引拍的速度，引拍才有的放矢，搓出去的球动作才协调。只要引拍的时间对上来球的时间，你的搓球就对一半了。在节奏掌握比较平稳之后，也不必像业余体校的小孩那样一搓上百板，只要能连续搓七、八板以上，击球点比较固定，而且能加转，弧线也不太高，就可以进入下一阶段的练习了。</p><p>4 拍形</p><p>拍形后仰具体多少度为好？不能规定那么细，大概30度左右。初学者有时候搓球太靠底部，优点是容易搓转，缺点是不好控制，容易冒高。30度左右的倾角，利于你发出力，纯粹搓底部不容易发力，对手腕手指的要求太高，所以，接触球体中部偏下就好。具体的角度，因来球也因人而异，每个人的手上感觉不一样，有的人天生拍形就比较立。只要有旋转、能控制、能搓转不转、弧线够低，就是好动作，就是合理的搓球，而不必斤斤计较于多1度还是少1度。无论直横拍，正手搓球的难度都比反手大：直拍牵扯到三个手指如何调整拍形的问题，搓正手的时候假如食指和中指握得太紧，拍形容易朝天，所以要手腕外展；横拍主要调节好食指，手腕要能打开，拍头不翘就好。</p><p>5 站位</p><p>无论直横拍，我们都建议用通常的基本站位，以右手为例，用不着左脚在右脚后面，否则以后再衔接进攻技术，腰全让右脚顶住了。</p><h4 id="练习路径" tabindex="-1">练习路径 <a class="header-anchor" href="#练习路径" aria-label="Permalink to “练习路径”">​</a></h4><p>1 反手搓斜线</p><p>先搓反手斜线，单线练习，掌握基本动作。喂球方供一般下旋球，不能快，否则初学者不容易掌握引拍的时间，也没有空间去加大摩擦。喂球越低越好，假如球太高，主练方不容易掌握击球时间。你想，喂球方是慢搓过来的，如果又慢又高，主练方什么时候挥拍啊?太痛苦了！喂球方需把球送到主练方偏反手一些(别到中路)，以促使主练方不自觉地接触球体的偏左一点，这样有三个好处：主练方肯定是回斜线，利于线路稳定；容易加转；用力方向想错都难，因为你“捅”着搓时肯定不是接触球体偏左。如果你找不准节奏，可以自己拿一盆球，左手把球拿到胸前，手背朝下，放开，让球在台面上垂直跳一下，右手挥拍搓球，再拿一个球，再放，再搓……一，二，三，就这三下，不怕慢，就怕不连续，多慢都可以，但是必须一球连上一球，就是为了培养节奏感。熟练之后，再把球拿开，徒手挥拍，体会搓球的动作。</p><p>2 反手搓直线</p><p>在第一步的基础上，找到一些搓球的感觉之后，搓斜线学会加转了，再练习反手搓直线。不会搓直线，你身体不用动，只要把接触球的点向球体正中间移一下，用力方向往正前一些，就没问题了。</p><p>搓球练习，要有一定的板数。搓球看上去像匀速运动，其实不然，中间是有节奏变化的，只有动作比较协调放松，才能再体会中间那一下变化——既要发力又要送，“慢中快”。刚开始，你可能只是把球碰过去，动作只是形似，有了一定板数之后，慢慢才能体会到摩擦的感觉，才有神似。先不说旋转，能控制拍形，能搓到球台底线任何一个点上，才能叫学会了搓球。</p><p>3 搓转不转球</p><p>掌握了基本的搓球加转，就要开始体会搓不转球。从理论上说，搓不转球触球时要“碰”而不摩擦，但到高级阶段，你还是要有摩擦的动作，但其实不发力，只是做给对手看，过去还是不转球。通过练习搓不转球，你会对手指手腕的运用更有感觉。</p><p>练习搓转不转时，最好是借助多球来喂球，给出的球不要太长，否则主练方会不知不觉容易离台，而人一离台，引拍就不知道往哪儿搁。</p><p>多数业余选手没有多球练习的条件，只能采用单球练习。那么，主练方练搓转不转，一板转一板不转，陪练方在应对不转时，拍形一定要稍微立一点，而且动作要有缓冲，假如是“捅”过去的，主练方下一板就没法搓了，球速太快，弧线太平，快改推挡了。先是板板搓加转，再板板搓不转球，再是两板转、两板不转，最终过渡到一板转、一板不转。</p><p>4 正手搓球</p><p>反手两条线(斜线、直线)都会搓之后，甚至会搓转不转之后，再练正手搓球。因为正手空间太大，动作变数太多，不易正确定形。同时，过早练习正手搓球，难免削弱正手攻球意识的培养，而正手攻球是所有技术中杀伤力最大的，所以正手必须先练攻球再练搓球。</p><p>正手也有搓转不转之分，但如果练习时间有限，可以只搓一般旋转的球，只要稳定、弧线低即可。你也可以借助发球练习来强化正手的搓球感觉，因为搓球与发下旋球的原理是互通的，两者必然能够互相促进。这样，既为练习增加了趣味性，又提高了时间的利用率。初学者可以正手先练一板发转不转球，再练侧下发球，最后练侧上发球。</p><p>正手搓球的练习可以比反手少很多，甚至1比10都可以，但是不能不会，否则日后你正手接发球时肯定会后悔。根据我们多年的教学经验，你一上手就这么练并不会觉得很难，如果等练了两三年已经形成某些基本习惯之后，你发现自己正手搓球不行，再回头来补课，还不如你刚开始痛苦两月呢。</p><p>正手没有反手搓的转不要紧，只要能搓出长度，弧线比较低、比较稳，单线能搓上四五板，对大多数业余选手就够用了。正手搓球不像拉球，拉球动作快，需要你全身的配合，尤其正手拉球，动作复杂得多，空间很大，搓球就比较慢，易干掌握，所以它是你正手学会制造旋转的重要手段，不可缺省。</p><p>笔者认为，正手搓球练习不必像反手那样搓“跳起来就出台”的球，因为日后实战中正手几乎碰不到那种球——可以直接拉而不必搓了。所以，就练习搓第一跳后几乎不出台或刚刚出台的球。</p><p>5 摆短</p><p>搓长练好了，再练摆短，先练中路、反手的摆短作为业余爱好者来说，对练摆短难度很大，有条件最，好是借助多球：陪练方站在网前喂球，刚刚过网，不用劲，便于主练方发力。实在没有多球，可以陪练方发球，主练方摆短，摆完之后，陪练方把球抓过来再发，如此往复。</p><h4 id="以搓为矛" tabindex="-1">以搓为矛 <a class="header-anchor" href="#以搓为矛" aria-label="Permalink to “以搓为矛”">​</a></h4><p>1 优化动作</p><p>双方都有一定能力之后，可以试着让搓的动作短促一点，手指、手腕的运用更讲究一点。练习摆短，不期望像国手那样摆过去在台内跳三下、四下，但至少练到跳两下。这时候，重心的重要性直线上升，一定要稳。有了这些之后，再讲究击球点，最初你搓的可能是来球的高点甚至下降期，现在要提前，在来球的上升期触球。一般而言，短球不可能像长球那么转，所以拍形可以稍微立起一些，这种摆短其实很忌讳拍形平着上前，因为特别容易搓长。你球拍立着一点，接触球的部位偏球体中心，这样过去至少弧线低，否则容易冒高、摆不短、加不转。为什么我们最初练习搓球的时候拍形要稍微后仰一点?因为那样容易加转、搓长。但随着练习程度的加深，技术越来越熟练，击球时间提前了，更容易借上对方来球的力量了，自己的拍形也就不用那么平了，平了反而麻烦。这时对球的控制，就靠你发力更集中，对缓冲掌握得更好，对触球部位的精确拿捏，甚至拍形到了45度还能加转。</p><p>开始练习摆短，只要弧线够低、够短就行，旋转有就行。对专业队来说，摆短肯定必须得转，但我们还是不太看重你搓得是否够转，我们强调的是你要够短，摩擦发力之后，用李晓东的话说，要有“忍”一下的感觉。要求得再多一点，就是动作始终要放松，这样以后水平高了，可以把加转的功夫再补上。业余选手常见的误区是，一碰到带旋转的技术，就喜欢把旋转放到第一位，其实不尽然，对乒乓球体会深一些的人就知道，这种理解其实是很大的误解。当然，在最初练习搓(长)球时，还是要搓得转，否则什么都是空话，而到了中高级阶段，你可以用其它的技术来弥补旋转的不足。也许会有人说，我就是对自己高标准严要求，上来就要练摆短加转，也不一定不对，但笔者的理解还是摆“短”第一。</p><p>顺便提一句，我认为直拍摆短时拍形可以纵着一点上前(即拍面与手臂一顺)，不必横向打开太多，这样的好处是动作有“根”。假如拍形过于横，尤其是直拍，容易失控。而且，你脚下也是纵着上去的，球拍与脚步同向，用力更自然流畅。</p><p>2 凝炼套路</p><p>这时候，需要注意的是切忌急于求成，这种问题在业余选手里非常普遍。许多人有这样一种概念，他认为自己掌握了不少乒乓球理论，就觉得自己也能使用那许多技术了，于是太过追求那些高精尖的技术。但他实际所掌握的东西，跟他的理论素养是不成比例的。也就是说，意识超前，而技术达不到。笔者并不反对业余选手练一些高难度的技术，但任何事情都是循序渐进，不是凭空起高楼的。</p><p>你要循序渐进这么练，打好了基础，再往深练，容易。业余选手可以说百分之九十都是从下旋打起，你说你搓球好占不占便宜?哪怕你不会摆短，不会快搓，只要能把长球搓到底线，能搓转不转，控制得特别好，弧线够低，已经算是业余很棒很棒的了。这是对初学者的要求，当然，下一步你可以练习综合技术了——发完球抢一板，或者对方发球我搓一板，再抢拉……练好了这些连接技术，你手里就不再是单一的技术，就可以晋升中级了。</p><p>以劈长为例，劈完长不可能还接着搓。无论对方是搓回来还是拉过来，来球一定不会太转，无论你是拉也好、打也好，总之要学会进攻劈长之后对方回过来的这板不转球。甚至，假如你的劈长不够快，对方抢先拉起来了，你还要进入相持甚至有点防守的状态，当然，这不是单纯的被攻，而是你先控制对方，对方看似挂起来了，其实你是上风，怎么打都可以，这些套路都是需要练的。</p><p>又比如，先练习搓完侧身拉，连续练习一段时间，有一定体会后，可以再练摆短后上手，反手挂一板，台内打一板……甚至可以要求你的练习伙伴，“现在我摆短之后你可以搓出台的，我两边上手，练连接。”这才能让你的搓球摆短比较快地进入实战的轨道中。</p><p>另外，可以有意让对方发带侧旋的球，你练拍形的控制，对侧旋的控制，如果你接发球都能搓到一个落点上，就证明你具备了控制侧旋的能力。</p><p>3 直横有别</p><p>直拍搓球与横拍最大的区别，在于直拍的拍形变化比较容易而且动作小，所以横拍选手练习搓球时握板最好不要太紧，略松一点较好，否则很容易造成正手接发球出现问题，那你在对手的发球面前就翻不了身了。当然，横拍搓球也有自己的优势——反手力量大，容易加转，横拍的英文是“Blade”，意为大刀，大刀可是砍过去的，而且横拍反手搓球是顺着转腰的方向用力，直拍这方面就有所不及。所以，在练习路径的选择上，横拍东西不要太杂，练精一点，直拍要么是拍形变化多，要么是那几下特别精，要根据本人特点，是以转不转为主?还是以变化为主?或者就是一个不转摆短?千万不要练成全会但全都不精，那就麻烦了。</p><p>4 掌握绝活</p><p>从初级到中级之后，如果有条件，不妨再练一些从搓球派生出来的技术：比如搓中“勾”一下，勾对方边线大角，又如撇着搓、抹着劈，其实都属于搓球的范畴。只要借好来球的旋转，搓过去的球既有速度，还不容易出界。对中级阶段来说，正是丰富自己搓球“武器库”里武器种类的时候，不再是单一的搓球。如果条件更好，身体够协调，脚下跑得快，你甚至可以练点侧身晃接。</p><p>但是，中国人打球，说到底，还是突出一个字，“巧”。业余高手，在这一点上，体现得尤其明显。很多业余相当不错的，并不是基本功有多么扎实，就是发球、接发球以及之后那两三板，特别精。短球怎么处理，反手怎么处理，侧身怎么处理……他处理的那些手法，从业余水平来说，要么技术质量很高，要么变化多，有成形的套路，而且命中率很高。比如接台内短球，我正手就是一板摆短，摆的是不转球，但摆得特别短，特别精。或者搓长球，就是常规的搓转不转，只要旋转反差特别大，也是高手。乒乓球运动里，不是哪项技术本身高明，而是使用者用得恰到好处，这才叫高明；不是说一个人会81种技术才叫高手，他就会四下，但每一下都能让对方没脾气，这才叫高手，精。比如我的技术特点是希望尽快把球变成上旋，而且人家打到我的反手，我也特别有把握，因为我变线特别好。那么，发完球，或者接发球，从使用搓球技术开始，就要围绕自己的特长来展开——对方发到我中路偏短，我要能劈长到对方中路、反手，速度要快，目的是逼住对方，使其一定回我反手，我不指望一板把你打死，我把你黏死，但前提是必须让对手回出上旋。我撇着、抹着搓，对方必须把球“拱”起来，只要一“拱”起来；就到我的球路上了。或者我摆短，就摆不转球，这样对方也不容易加转，球一回过来，我反手“拱”起来特别快，一下到对方中路，对方变不了线，还是回我反手，又到我球路上了。又比如我是直拍，我希望对方回球到我反手位，然后我侧身给他一下，搓球的时候就要讲究了，要么旋转有变化，转不转差别特别大，要么是连续搓他中路。如果你搓得有一定旋转、速度很快，他很难变线，至少难以大角度变到你正手位。这样，我就用我所有的接发球技术控制住对方，迫使他回球到我反手位，无论搓转不转、快搓慢搓都是围绕这个目的，这时你的搓球本身已经具有一定的攻击性了。也只有这样去使用搓球，才能全面体现它的内涵。</p><p>又比如对阵横拍，其发球很少有纯粹转不转的，都是侧上、侧下旋居多，这时，搓球的好坏还涉及到搓侧旋的问题，既要判断上、下旋，又要判断左、右侧上、下旋的侧旋程度，这对拍形的掌握、火候的拿捏，要求很高。比如你同这个横拍打了两局后，知道这个人爱发内侧上、下旋，你就可以撇着接(顺着接容易出界)。你既要控制他的发球，还要令下一板他不好打、你好打。这样的搓球，即便不能直接得分，也是与自己的技战术有机地结合了起来。再如碰到长胶，就不能采用常规搓球了，你得挤着搓，拍形立着搓，只要你能把球搓长、搓转了，长胶就只有半条命了，因为它最喜欢的是半长不短的球，一搓你就冒，它不是“捅”你就是“拱”你。如果你发球特别转，紧接着一板搓长追身，顶着长胶，它一碰就下网，你用搓球就搓死它。所以说，在某种意义上，怪拍对手(长胶、生胶、防弧)，就是检验你搓球水平的试金石。</p><p>业余选手总认为搓球是一项中性技术，甚至根本不是得分手段，因而忽视它。错了!只要搓球搓得好，完全可以把对方彻底“钉”在那儿动不了。马林跟金择洙比不了连续，跟柳承敏比不了快速扑正手，为什么还能成为顶尖高手?他台上那“十八下”太厉害了，折腾得对方找不到击球点，所以他总能有正手那一板后续进攻。笔者举出马林的例子，并不是给大家提那么高的要求，而是想说，业余选手到一定“段位”也应该有些追求，不是单为了赢球，还得有境界，这样球才越打越过瘾，越有味道，有学问有讲究。</p><hr><h2 id="第五部分-【网友探讨】关于重心转移与用腰的讨论" tabindex="-1">第五部分：【网友探讨】关于重心转移与用腰的讨论 <a class="header-anchor" href="#第五部分-【网友探讨】关于重心转移与用腰的讨论" aria-label="Permalink to “第五部分：【网友探讨】关于重心转移与用腰的讨论”">​</a></h2><hr><h3 id="就武术发力说明几个问题" tabindex="-1">就武术发力说明几个问题 <a class="header-anchor" href="#就武术发力说明几个问题" aria-label="Permalink to “就武术发力说明几个问题”">​</a></h3><p>武术的发力，就是把力量瞬间的爆发出去。它只是武术的一个组成部分。武术说白了也就包括，技巧、发力和功力这几个部分。可见发力在武术当中是有着重要作用的。</p><p>瞬间爆发：最短的时间最突然地把蓄积的力量释放出去。我们打乒乓球时多数人爆发的意识不明显，出手软绵绵，主要表现在意识都集中在使球上台上了，想要爆冲没爆力发力能行吗！还有就是多数人把引板当成过渡，其实引板就是蓄力。比喻一下就把弓拉满，什么是弓，身体（腰）就是弓。什么是弦，拍就是弦。而球就是箭（在拍的加速下的离弦之箭）。突然性是武术的需要，在乒乓球里大家自己讨论吧。这一段主要就是强调瞬间爆发的意识问题。</p><p>放松：人体的肌肉很多块，每块的作用不同，我们弯曲手臂的时间有的肌肉拉缩，有的肌肉申张。不能放松肌肉有的就会阻碍运动，影响发力。我们在练习出拳或出脚时，就要体会哪些肌肉在拉缩或在申张（积极的）哪些在阻碍（消极的），主动的强化积极的肌肉群，放松消极的肌肉群。</p><p>腰、背：在武术中不会用这两个力的人，跟本就不算入门。有人认为足下发力多么多么重要。我说你是一知半解。没见过武术运员空中发力，你还没见过打排球啊！打乒乓球的朋友多体会用上腰背的力量。才能真正的学会发力！这点很重要！</p><p>有两个训练方法。能否运用好，自己去体会吧！只可意会（和资质有关），呵呵。I的资质也不太好。。。。。。</p><p>放松你的肌肉，静静的体会按挥拍的路线挥动你的球拍。</p><p>绷紧你的肌肉用尽你的力气缓缓的按挥拍的路线挥动你的球拍。</p><hr><h3 id="对重心转移与用腰的思考" tabindex="-1">对重心转移与用腰的思考 <a class="header-anchor" href="#对重心转移与用腰的思考" aria-label="Permalink to “对重心转移与用腰的思考”">​</a></h3><p>有人把攻球动作中的重心和腰的运动方式理解为类似于一扇门的转动，说门是围绕一个轴转的,而我们攻球动作中的这个轴就是我们身体的中轴，因此腰和重心都是围绕着这个&quot;轴&quot;运动的一个扇形轨迹。持此论者还举出了雨伞的转动使雨水向四处飞溅和链球在运动员身体的加速旋转后飞向远方的例子来说明自己的观点，并把这种门轴式的动作称之为&quot;圆周运动&quot;。</p><p>这种理解值得作进一步的讨论。</p><p>我所认识的一球友在谈打球体会时就不说什么重心，而是强调说&quot;扭螺丝&quot;（指击球时身体的旋动）；但我观察他拉球时磨擦过多，力量不大。他单位的同事戏称其&quot;某小板&quot;（&quot;某&quot;是此球友之姓）。&quot;扭螺丝&quot;式与&quot;门轴式转动&quot;类似，它最大的问题是力量的耗散。就以&quot;伞的转动使雨水向四处飞溅&quot;为例，可以发现&quot;四处飞溅&quot;的雨滴在离心力作用下并没飞向我们心目中的击球方向，而是沿切线方向朝&quot;四面八方&quot;分散掉了。可见腰的转动有一个度的把握问题在。我记得张晓蓬教练（电视教学片：《打好乒乓球》中的直板教练）在一篇文章中就特意说明他不赞成拉球引拍时腰沿垂直轴方向旋转过多。拉球不同于无须考虑还原的掷铁饼运动，前者要在有一定的垂直方向旋转的同时注意要有沿纵向轴方向的压转，这样才能有效地发挥出击球时腿、腰、手要&quot;同时向同一方向集中用力&quot;的功力。所以重心转移始于足：蹬地，要有从右腿往两腿间的重心转移——但身体不能上下起伏（是重心平动）！身体各部分朝击球要去的方向同时用力，转腰也就在此中了；至于&quot;圆周运动&quot;，不是指转动雨伞甩雨滴或链球运动的旋转方式，而是指重心转移&quot;在击球瞬间找到一个支点，使击球重心在瞬间保持一个停顿&quot;（王吉生教练语），从而使手臂的鞭打式发力得以优化的发力方式。故此圆周非彼圆周也。</p><p>需要说明的是，上文所引王吉生教练所言之&quot;停顿&quot;之意不是指攻球&quot;后&quot;的制动，而是指持拍手一侧的髋关节在重心移动中的突然刹车——手臂的鞭打效应：&quot;甩&quot;的作用力，就产生于这关键的&quot;中枢&quot;传导站。</p><p>我之所以不赞成用容易引起误解的简单的&quot;门轴式转动&quot;的圆周运动来说明攻球运动，是因为这种理解的似是而非。在讨论近台快速相持的问题时，李晓东教练是强调要以重心来带动手臂的还原或引拍的。他用了下面三个句子来表述：&quot;手在台面上（即手的位置要保持在不低于台面的高度上）；手在身体前面（即不要在还原时将手扯到身后去）；手在肘前面（许多球友无法还原接第二板球，造成&quot;身后击球&quot;，就是拉手过于靠后的缘故）。&quot;李晓东教练的这三个对&quot;手的空间位置&quot;的限定词，就是不让你在还原或引拍时做过多的什么&quot;门轴式旋转&quot;；他所说的&quot;用重心带动手臂还原&quot;，就是让重心向右腿转移时使手臂向身右侧位自然落放或称横摆，而非&quot;跑步式&quot;后拉手。发力要想不耗散掉，也只有在还原或引拍时不做张晓蓬教练所不赞成的过分逆向门轴式的旋转才有可能。这里就有一个会否用腰的问题在。</p><p>即使是拉弧圈之从迎球到击球再到随挥的动作，我为什么也不赞成形容为门轴式的圆周运动？是因为它表达不清楚重心移动中腰在其中的作用。腰在拉球动作中起的是一个中枢传导站的作用，是所谓画圆周运动&quot;甩鞭&quot;制动的中心和&quot;柄&quot;。以此为轴心甩出来的扇形与一般皮相理解中的上下一根筋的门轴式均匀转动是不同的；前者不是&quot;身体向前的平动和绕垂直轴转动的合成运动&quot;所能准确说明的。</p><p>我认为，上下一根筋式的门轴式转动是&quot;无腰&quot;的转动——因为这种描述根本体现不出腰的作用。但吴敬平教练在一篇谈拉球的文章里又分明说过&quot;乒乓球运动基本上是一项圆周运动&quot;的话，这该如何理解呢？在尝试解答之前，让我们先重温一下吴教练的原话：&quot;正手和反手拉球都是以运动员的身体重心为轴心、以身体到身体重心的连线为半径进行圆周运动。&quot;在吴教练看来，正反手拉球动作的基本原理是一种&quot;力的传递&quot;。通过什么传递？正是中枢传导站的腰！这种圆周运动如果可以借用&quot;扇形&quot;来作比喻的话，那它的运动轨迹就不是门扇沿门轴活动的那种中规中矩的均匀扇形，而是有如家用风扇的涡形叶扇形态。为了能更形象地说明这种力的传递所走过的扇形轨迹，让我们试着想象一只漏斗。把腰的中枢传导站想象为漏斗的出水椎口处（这是一个重要的爆发点），由执拍手甩出的扇形弧线就是沿漏斗丫形内壁自下而上地呈斜线展开的。这种扇形的圆周运动与门轴式的、上下一根筋的扇形的圆周运动的动态结构难道可以混为一谈吗？</p><p>涡形叶扇的形态或漏斗式的扇形都只是一种比喻，它诉诸于想象力。而任何比喻都是跛足的，经不住硬抠；能意会即可。</p>',397)),e(l),e(r)])}const x=i(n,[["render",d]]);export{P as __pageData,x as default};
